window.__D("text/zohar-hebrew-translation/c039",{"p":[[9522012742,"<p>שֶׁהֵם אֶחָד, נָהָר וְגַן. נָהָר שֶׁיּוֹצֵא מֵעֵדֶן וְגַן שֶׁהֻשְׁקָה מִמֶּנּוּ. כָּאן כָּל הַסּוֹד הַסָּתוּם שֶׁל הָאֱמוּנָה. וְלָמַדְנוּ שֶׁמִּי שֶׁמִּתְעוֹרֵר בַּלַּיְלָה בְּאוֹתָהּ שָׁעָה שֶׁנִּכְנָס הַקָּדוֹשׁ בָּרוּךְ הוּא יַחַד עִם הַצַּדִיקִים בַּגָּן, צָרִיךְ לוֹמַר פָּסוּק זֶה בִּרְצוֹן הַלֵּב וּלְכַוֵּן דַּעְתּוֹ בּוֹ, וְאַחַר כָּךְ אוֹדְךְ עַל כִּי נוֹרָאוֹת נִפְלֵאתִי נִפְלָאִים מַעֲשֶׂיךְ וְנַפְשִׁי יֹדַעַת מְאֹד. (ואחר כך ונהר יצא מעדן וגו'). וְזֶהוּ שֶׁבַח הַחֲסִידִים הָרִאשׁוֹנִים כְּשֶׁהִתְעוֹרְרוּ בַּחֲצוֹת הַלַּיְלָה, וְאַחַר כָּךְ מְסַדְּרִים הַשֶּׁבַח שֶׁלָּהֶם וְעוֹסְקִים בַּתּוֹרָה.</p>\n<p>מַהוּ שַׁעֲשׁוּעוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא כָּל הַצַּדִּיקִים שֶׁעוֹמְדִים בִּדְמֻיּוֹתֵיהֶם וּמִתְלַבְּשִׁים בַּגָּן בְּכָל יוֹם וָיוֹם, כֵּיוָן שֶׁרוֹחֲצִים בַּטַּל שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת בּוֹ מֵתִים, נִכְנָסִים כֻּלָּם לַמָּשִׁיחַ וְשׁוֹאֲלִים מַה שֶּׁשּׁוֹאֲלִים, וַהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים.</p>\n<p>אַחַר כָּךְ מִתְכַּנְּסִים וּמִשְׁתַּדְּלִים כֻּלָּם בְּדַעַת עֶלְיוֹנָה בְּכָל הַיְשִׁיבוֹת שֶׁשָּׁם, וַעֲלֵיהֶם כַּמָּה מְמֻנִּים, וּמִתְחַדְּשִׁים שָׁם כַּמָּה חִדּוּשִׁים בַּתּוֹרָה. אַחַר כָּךְ יוֹצְאִים כֻּלָּם וְרוֹאִים כְּשֶׁבָּא אֵלִיָּהוּ לָאָבוֹת, הוּא יוֹצֵא וְהֵם נִכְנָסִים, וְעוֹמְדִים לִפְנֵי הָאָבוֹת, וּשְׂמֵחִים בָּהֶם וּבְכַמָּה בָנִים קְדוֹשִׁים שֶׁסְּבִיבָם וּשְׂמֵחִים כֻּלָּם.</p>\n<p>כְּשֶׁנִּכְנָס הַקָּדוֹשׁ בָּרוּךְ הוּא בַּחֲצוֹת הַלַּיְלָה, כֻּלָּם עוֹמְדִים מְתֻקָּנִים כָּרָאוּי, וְכָל הַהִשְׁתַּדְּלוּת שֶׁהִשְׁתַּדְּלוּ כָּל אוֹתוֹ הַיּוֹם בְּחִדּוּשֵׁי תוֹרָה, תַּאֲוַת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָם צַדִּיקִים שֶׁחִדְּשׁוּ בָהּ דְּבָרִים, וּמִשְׁתַּעֲשֵׁעַ בָּהֶם וּבְאוֹתָם הַדְּבָרִים.</p>\n<p>אַחַר כָּךְ כֻּלָּם מְתֻקָּנִים זָכָר וּנְקֵבָה, וְאַחַר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֵרִיחַ וְהִשְׁתַּעֲשַׁע בָּהֶם בְּכָל אוֹתָם דְּבָרִים סוֹדוֹת חָכְמָתָם, מִתְגַּלֶּה עֲלֵיהֶם, וְהֵם רוֹאִים בְּאוֹתוֹ נֹעַם ה', אָז כֻּלָּם שְׂמֵחִים בְּחֶדְוָה רַבָּה עַד שֶׁמִּתְפַּשֵּׁט זִיוָם וְאוֹרָם, וּמֵאוֹתוֹ הֶמְשֵׁךְ זִיו וְאוֹר שֶׁל חֶדְוָה שֶׁלָּהֶם עוֹשִׂים פֵּרוֹת וְתוֹלָדוֹת לָעוֹלָם הַזֶּה, וְאוֹתוֹ פְּרִי וְתוֹלָדָה נִכְנָס תַּחַת כַּנְפֵי הַשְּׁכִינָה עַד זְמַן שֶׁצָּרִיךְ.</p>\n<p>וְכָךָ מִשְׁתַּעֲשֵׁעַ בְּכָל צַדִּיק וְצַדִּיק, (ואמר) וְאוֹמְרִים: אַשְׁרֵי הַמֶּלֶךְ שֶׁבָּנִים הַלָּלוּ נִבְרְרוּ לְחֶלְקוֹ וְגוֹרָלוֹ! קוֹל מִתְעוֹרֵר מֵאֶמְצַע הָרָקִיעַ וְקוֹרֵא בְקוֹל חָזָק וְאוֹמֵר: זְכֹר ה' לִבְנֵי אֱדוֹם אֵת יוֹם יְרוּשָׁלם הָאֹמְרִים עָרוּ עָרוּ עַד הַיְסוֹד בָּהּ. וְאָז רַעַשׁ הַשִּׂמְחָה שֶׁלּוֹ וְהַקִּרְקוּר שֶׁלּוֹ וּמִכָּל הַצַּדִּיקִים שֶׁשָּׁם נִשְׁמָעִים בִּשְׁלֹשׁ מֵאוֹת וְתִשְׁעִים רְקִיעִים,</p>\n<p>מִשּׁוּם שֶׁאֵין חֶדְוָה וְשַׁעֲשׁוּעַ לַקָּדוֹשׁ-בָּרוּךְ-הוּא אֶלָּא בְּשָׁעָה שֶׁעוֹמְדִים בָּהֶם (שעומד יחד עם) הַצַּדִּיקִים שֶׁשָּׁם, וּמִשּׁוּם זֶה נִשְׁבַּע וְאָמַר: אִם אֶשְׁכָּחֵךְ יְרוּשָׁלם תִּשְׁכַּח יְמִינִי תִּדְבַּק לְשׁוֹנִי לְחִכִּי אִם לֹא אֶזְכְּרֵכִי אִם לֹא אעלה את ירושלים על ראש שִׂמְחָתִי. בְּכָל מָקוֹם שֶׁיֵּשׁ חֶדְוָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא, קוֹל זֶה יוֹצֵא וְקוֹרֵא.</p>\n<p>אָז יוֹצֵא מִשָּׁם וְעוֹלֶה וּמַכֶּה רְקִיעִים וְשׁוֹאֵג שְׁאָגוֹת, עַד שֶׁכָּל חֵילוֹת הַשָּׁמַיִם כֻּלָּם בְּרַעַשׁ הַשִּׂמְחָה, וְאָז נוֹשֶׁבֶת רוּחַ וּמַכָּה בֶעָלִים שֶׁל אוֹתוֹ אִילָן גָּדוֹל, וְכָל הָעֲנָפִים שֶׁלּוֹ מַכִּים זֶה בָּזֶה, וְקוֹל מִתְעוֹרֵר מִתּוֹךְ נוֹף הָאִילָן, וְקוֹרֵא וְאוֹמֵר: זָכַר לְעוֹלָם בְּרִיתוֹ דָּבָר צִוָּה לְאֶלֶף דּוֹר אֲשֶׁר כָּרַת אֶת אַבְרָהָם וּשְׁבוּעָתוֹ לְיִצְחָק. כֵּיוָן שֶׁקּוֹל זֶה מִתְעוֹרֵר, שׁוֹמֵעַ אַבְרָהָם סָבָא וּמִתְעוֹרֵר, (אז) כַּאֲשֶׁר הוּא רָצוֹן לַמֶּלֶךְ, וּמִתְנַחֵם אִתּוֹ.</p>\n<p>בְּאוֹתָהּ שָׁעָה מִתְעוֹרֶרֶת רוּחַ אַחַת מִצַּד דָּרוֹם, וְכָל רָצוֹן וְחֶדְוָה וּרְפוּאָה מִתְעוֹרְרִים עַל הָעוֹלָם. וְאָז עוֹלֶה הַבֹּקֶר, וְנִמְצָא רָצוֹן וּמְנוּחָה לְכָל אֲסִירֵי הַמֶּלֶךְ שֶׁהֵם בְּבֵית חוֹלִים. אַשְׁרֵי הָעָם שֶׁיְּכוֹלִים לָדַעַת מֵהַסּוֹדוֹת הַטְּמִירִים וְהַנִּסְתָּרִים שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>אָמַר רַבִּי אַבָּא, יוֹם אֶחָד הָיִיתִי אֲנִי וְרַבִּי יְהוּדָה שֶׁמִּן עַכּוֹ (הולכים) בַּמִּדְבָּר, וְנִכְנַסְנוּ בִמְעָרָה אַחַת, וּמָצָאנוּ שָׁם סֵפֶר עַתִּיק אֶחָד מִיָּמִים רִאשׁוֹנִים. פָּתַחְנוּ אוֹתוֹ, וּמָצָאנוּ שֶׁהָיָה כָּתוּב בּוֹ בְּרֹאשׁ דְּבָרָיו: (ישעיה מב) הָרִאשׁוֹנוֹת הִנֵּה בָאוּ וַחֲדָשׁוֹת אֲנִי מַגִּיד, וּבֵאֵר הַפָּסוּק בְּנִשְׁמוֹת הַצַּדִּיקִים. מִיּוֹם שֶׁעָלָה בְמַחֲשָׁבָה לִבְרֹא עוֹלָם.</p>\n<p>וְעַד שֶׁלֹּא נִבְרָא הָעוֹלָם, כָּל רוּחוֹת הַצַּדִּיקִים הָיוּ גְנוּזוֹת בְּמַחֲשָׁבָה לְפָנָיו, וְכָל אֶחָד וְאֶחָד בִּדְמוּתוֹ. כֵּיוָן שֶׁצִּיֵּר אֶת הָעוֹלָם, הִתְגַּלּוּ כֻלָּם וְעָמְדוּ בִדְמוּתָם לְפָנָיו בְּרוֹמֵי מְרוֹמִים, אַחַר כָּךְ נָתַן אוֹתָם בְּאוֹצָר אֶחָד בְּגַן עֵדֶן שֶׁלְּמַעְלָה, וְאוֹתוֹ אוֹצָר לֹא מָלֵא לְעוֹלָמִים, וְתָמִיד קוֹרֵא: הָרִאשּנוֹת הִנֵּה בָאוּ וַחֲדָשׁוֹת אֲנִי מַגִּיד. מַה הֵם אֲנִי מַגִּיד כֻּלָּם בְּשֵׁמוֹת. וְאֵין תַּאֲוָה וְכִסּוּף לָאוֹצָר הַזֶּה, אֶלָּא רַק לְהוֹרִיק בּוֹ נְשָׁמוֹת תָּמִיד. כְּמוֹ שֶׁלַּגֵּיהִנָּם אֵין תַּאֲוָה וְכִסּוּף אֶלָּא רַק לְקַבֵּל נְשָׁמוֹת לְטַהֵר שָׁם. וְכָל יוֹם קוֹרֵא: הַב הַב. מַה זֶּה הַב הַב? (אלא) שְׂרֹף שְׂרֹף.</p>\n<p>וְאוֹתוֹ אוֹצָר לוֹקֵחַ כָּל (אותן) הַנְּשָׁמוֹת הַלָּלוּ, עַד זְמַן שֶׁמַּלְבִּישָׁם וּמוֹרִידָם לָעוֹלָם הַזֶּה, וּמִתּוֹךְ חֵטְא אָדָם הָרִאשׁוֹן שֶׁהִמְשִׁיךְ צַד הָרָע לָעוֹלָם, הִצְטָרְכוּ לְהַלְבִּישׁ אוֹתָן נְשָׁמוֹת בִּלְבוּשׁ זֶה, שֶׁהֲרֵי לְבוּשׁ אַחֵר רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַלְבִּישׁ לְאוֹתָן הַנְּשָׁמוֹת. (ואמר באותו ספר) וְהַהוּא (והיה) אָמַר אוֹתוֹ סוֹפֵר: עַד כָּאן שִׁתְקוּ (שתקו). וְעוֹד רָאִיתִי מִכָּאן וָהָלְאָה אוֹתִיּוֹת מְחוּקוֹת שֶׁלֹּא יְדוּעוֹת.</p>\n<p>וְאַחַר כָּךְ רָאִיתִי אוֹתָן בַּחֲלוֹם, וְאָמְרוּ לִי: שְׁתֹק וְאַל תְּגַלֶּה, אֶלָּא לַסֶּלַע הַתַּקִּיף. וְכָךְ עָשִׂיתִי. וּמָצָאתִי בוֹ שֶׁכֵּלִים שֶׁל לְבוּשׁ אַחֵר עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַלְבִּישׁ אֶת אוֹתָן נְשָׁמוֹת לַעֲתִידִים (לעתיד) לָבא. (אם כן,) מֵתִים שֶׁחָיוּ עַל יְדֵי יְחֶזְקֵאל, מָה הַטַּעַם לֹא עָשָׂה לָהֶם אֶת אוֹתוֹ הַלְּבוּשׁ?</p>\n<p>אֶלָּא מִשּׁוּם שֶׁלֹּא הִגִּיעַ זְמַן לְהַעֲבִיר בָּעוֹלָם אוֹתוֹ אֲוִיר טָהוֹר שֶׁעוֹשֶׂה לְבוּשִׁים, וּמִשּׁוּם זֶה לֹא הִלְבִּישָׁם אֶלָּא כְּמוֹ שֶׁהֵם הָיוּ, וְכָךְ יִהְיֶה לִתְחִיַּת הַמֵּתִים, פְּרָט שֶׁאוֹתָהּ זֻהֲמָא שֶׁל הַהַתְחָלָה לֹא נִמְצֵאת שָׁם.</p>\n<p>כְּשֶׁיּוֹצֵא אָדָם מֵהָעוֹלָם הַזֶּה, כֻּלָּם, בֵּין צַדִּיקִים בֵּין חֲסִידִים וּתְמִימִים וּרְשָׁעִים וְחַיָּבִים, כֻּלָּם עוֹבְרִים בְּדֶרֶךְ זוֹ לִרְאוֹת אֶת אָדָם הָרִאשׁוֹן לִבְנֵי הָעוֹלָם, וּמִשָּׁם לוֹקְחִים דֶּרֶךְ, הֵן לְגַן עֵדֶן הֵן לְגֵיהִנָּם.</p>\n<p>כָּל אוֹתָם שֶׁדַּרְכָם לְגַן עֵדֶן, מִתְקָרְבִים לַחוֹמָה הַחִיצוֹנִית מֵאוֹתָן שָׁלֹשׁ חוֹמוֹת שֶׁשָּׁם, וְאָז יוֹצֵא מְמֻנֶּה אֶחָד, וּמִתְעוֹרֵר לִפְנֵיהֶם וְקוֹרֵא וְאוֹמֵר: אַשְׁרֵיכֶם הַצַּדִּיקִים (בכל העולמות) בָּעוֹלָם! וְאוֹתוֹ מְמֻנֶּה, שְׁמוֹ יַעְזְרִאֵ\"ל, מְלַמֵּד אוֹתָם אֶת הַדֶּרֶךְ, וְהוֹלְכִים לְפָנָיו עַד שַׁעַר אֶחָד שֶׁל הַגֵּיהִנָּם, וְאוֹתוֹ מְמֻנֶּה קוֹרֵא בְחַיִל וְאוֹמֵר: צַנְּנוּ הֶעָשָׁן! צַנְּנוּ הַשְּׂרֵפָה! בְּאוֹתָהּ שָׁעָה מְצַנְּנִים אוֹתָהּ בִּבְהִילוּת, וְנִכְנָסִים כֻּלָּם וְטוֹבְלִים וְעוֹבְרִים, וְכָל אוֹתָם רְשָׁעִים נִמְסָרִים בְּיַד דּוּמָ\"ה וְנִכְנָסִים בַּגֵּיהִנָּם, וְכָל אוֹתָם צַדִּיקִים לֹא נִמְסָרִים בְּיָדָיו, אֶלָּא (בידי) הַמְמֻנֶּה הַזֶּה.</p>\n<p>וְאַחַר שֶׁטּוֹבְלִים וְעוֹבְרִים, הַמְמֻנֶּה הַזֶּה הוֹלֵךְ לִפְנֵיהֶם עַד שֶׁמַּגִּיעִים לְחוֹמַת גַּן עֵדֶן, וְאוֹתוֹ מְמֻנֶּה קוֹרֵא לַפֶּתַח וְאוֹמֵר: פִּתְחוּ שְׁעָרִים וְיָבֹא גוֹי צַדִּיק שֹׁמֵר אֱמֻנִים (ישעיה כו). אָז פּוֹתְחִים פֶּתַח וּמַכְנִיסִים אוֹתָם, וְכָךְ בְּכָל פֶּתַח.</p>\n<p>כֵּיוָן שֶׁנִּכְנְסוּ לְתוֹךְ מָקוֹם שֶׁצַּדִּיקִים אֲחֵרִים עוֹמְדִים, כַּמָּה חֶדְוָה עַל חֶדְוָה עַל הַצַּדִּיקִים, וְכָל בְּנֵי הַיְשִׁיבָה שְׂמֵחִים. לְסוֹף שְׁלֹשָׁה יָמִים שֶׁמִּתְחַבְּאִים בְּהֵיכָלוֹת יְדוּעִים, יוֹצְאִים וַאֲוִירִים נוֹשְׁבִים, וּמִצְטַיְּרִים כֻּלָּם בִּדְמֻיּוֹתֵיהֶם. מִכָּאן וָהָלְאָה יוֹרְשִׁים יְרֻשָּׁה כָּרָאוּי לְכָל אֶחָד וְאֶחָד.</p>\n<p>מַרְאֶה שֶׁנִּרְאֶה בְּגַן עֵדֶן מִמַּרְאֶה נִכְבָּד, דְּמוּת כָּל הַדְּמֻיּוֹת, וְגָוֶן שֶׁל כָּל הַגְּוָנִים. שֶׁמֶּלֶךְ הַקָּדוֹשׁ לֹא מִתְגַּלֶּה בַּהֵיכָל וְלֹא בְמָקוֹם אֶחָד, אֶלָּא נִפְתָּח רָקִיעַ מְרֻקָּם עַל גַּב הַגָּן לְאַרְבָּעָה צְדָדִים, וּמִתְמַלֵּא מִזִּיו כָּבוֹד הַקָּדוֹשׁ וְנִרְאֶה שָׁם, וְנֶהֱנִים כָּל הַצַּדִּיקִים. מִי רָאָה חֶדְוָה וְכִסּוּף קָדוֹשׁ שֶׁל אוֹתוֹ נֹעַם ה'.</p>\n<p>עַד כָּאן הָיָה לִי רְשׁוּת לִרְאוֹת בְּאוֹתוֹ סֵפֶר. כְּשֶׁהִקַּפְנוּ לִרְאוֹת בּוֹ יוֹתֵר, פָּרַח מִיָּדִי וְלֹא רָאִיתִי אוֹתוֹ. נִשְׁאַרְתִּי עָצוּב וּבָכִיתִי, יָשַׁנְתִּי שָׁם בְּאוֹתָהּ מְעָרָה וְרָאִיתִי אוֹתוֹ (את אותו) שֶׁהָיָה לָבוּשׁ מַדִּים. אָמַר לִי, רַבִּי, לָמָּה לְךְ לִבְכּוֹת? וְאַל תִּתְעַצֵּב (ממי) מִמַּה שֶּׁהָיָה בְּאוֹתוֹ סֵפֶר. פָּרַח אֵלָיו וּלְקָחוֹ, וְעַד שֶׁלֹּא יָצָא מֵהָעוֹלָם הַזֶּה, גָּנַז אוֹתוֹ בְּאוֹתָהּ מְעָרָה שֶׁבַּמִּדְבָּר הַזֶּה, וְכָעֵת שֶׁהָיָה מִתְגַּלֶּה לַחַיִּים כָּאן, פָּרַח בָּאֲוִיר וּלְקָחוֹ.</p>\n<p>מִכָּאן וָהָלְאָה לֵךְ לְדַרְכְּךְ. וּמֵאוֹתוֹ יוֹם וְעַד עַכְשָׁו לֹא הִתְגַּלָּה לִי וְלֹא זָכִיתִי לִשְׁמֹעַ מִמִּי הָיָה, וּבְכָל זְמַן שֶׁאֲנִי נִזְכָּר, אֲנִי נִשְׁאָר עָצוּב. אָמַר רַבִּי אֶלְעָזָר, אוּלַי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִכְבוֹדוֹ שֶׁלֹּא רוֹצֶה שֶׁיִּתְגַּלֶּה בָּעוֹלָם. עֵד שֶׁיָּשְׁבוּ וְעָסְקוּ בִּדְבָרִים אֲחֵרִים עֶלְיוֹנִים וְנִכְבָּדִים, הֵאִיר הַיּוֹם. קָמוּ וְהָלְכוּ. אָמַר רַבִּי אֶלְעָזָר, כָּעֵת עֵת רָצוֹן מִלִּפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, נֹאמַר דִּבְרֵי תוֹרָה וְנִתְעַסֵּק בָּהּ וְנִשְׁתַּתֵּף בַּשְּׁכִינָה. פָּתַח וְאָמַר, ה' בֹּקֶר תִּשְׁמַע קוֹלִי בּקֶר אֶעֱרָךְ לְךְ וַאֲצַפֶּה. אָמַר רַבִּי אֶלְעָזָר, בִּלְעָם הָרָשָׁע מִי הָרַג אוֹתוֹ, וְאֵיךְ נֶהֱרַג? אָמַר רַבִּי יִצְחָק וְכֻלֵּי: ע\"כ מההשמטות.</p>"],[9522012743,"<p>לֵאמֹר הִנֵּה עַם יָצָא מִמִּצְרַיִם. אִם תֹּאמַר שֶׁהֲרֵי צָרִיךְ לָקַחַת שֵׁמוֹת וְיוּחֲסִין שֶׁלָּהֶם - לֹא צָרִיךְ, אֶלָּא דֶּרֶךְ כְּלָל, שֶׁכָּתוּב הִנֵּה עַם יָצָא. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּךְ קָרָא לָהֶם הַפַּטְרוֹן שֶׁלָּהֶם כַּמָּה פְעָמִים. וְעַל זֶה אַל תִּטְעֶה שֶׁכָּתוּב שַׁלַּח אֶת עַמִּי, בְּכָל זְמַן.</p>\n<p>וְעוֹד, כְּשֶׁלָּקַחְתָּ עֵצָה עֲלֵיהֶם עִם פַּרְעֹה, בְּלָשׁוֹן זֶה יָכֹלְתָּ לָהֶם, שֶׁכָּתוּב הִנֵּה עַם בְּנֵי יִשְׂרָאֵל רַב וְעָצוּם מִמֶּנּוּ. גַּם כָּאן, שֶׁכָּתוּב הִנֵּה עַם יָצָא מִמִּצְרַיִם. וְלֹא הוֹצִיא אוֹתָם אַחֵר, אֶלָּא הוּא מֵעַצְמוֹ יָצָא, וּמִשּׁוּם כָּךְ תּוּכַל לְהָרַע לָהֶם.</p>\n<p>הִנֵּה כִסָּה אֶת עֵין הָאָרֶץ. יֵשׁ אוֹמְרִים, סִיחוֹן וְעוֹג שֶׁיִּשְׂרָאֵל הָרְגוּ אוֹתָם, שֶׁהָיוּ עֵין הָאָרֶץ. אֶלָּא כְּשֶׁהֵבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא אַרְבֶּה עַל אֶרֶץ מִצְרַיִם, כָּתוּב וַיְכַס אֶת עֵין כָּל הָאָרֶץ וַתֶּחְשַׁךְ הָאָרֶץ, לָמָּה? מִשּׁוּם שֶׁכָּל מְכַשְּׁפֵי וְקוֹסְמֵי הָעוֹלָם לֹא יָכְלוּ לַעֲשׂוֹת כְּשָׁפִים, אֶלָּא רַק דָּבָר אֶחָד בְּדַרְגָּה אַחַת בִּזְמַן אֶחָד, וְעַם זֶה הֵבִיא עָרֹב מְבֻלְבָּל מִכַּמָּה מִינִים מְבֻלְבָּלִים אֵלּוּ בְאֵלּוּ, עַד שֶׁלֹּא יָכְלוּ כָּל מְכַשְּׁפִים וְקוֹסְמִים לַעֲמֹד, וְזֶהוּ וַיְכַס אֶת עֵין כָּל הָאָרֶץ, וְכָאן כָּתוּב וַיְכַס אֶת עֵין הָאָרֶץ, וְכָךְ הוּא וַדַּאי.</p>\n<p>אָמַר רַבִּי אַבָּא, בָּלָק וּבִלְעָם לֹא הָיוּ בָעוֹלָם מְכַשְּׁפִים וְקוֹדְמִים כְּמוֹתָם. (בלעם), חֵילוֹ וְכֹחוֹ הָיָה בְּפִיו וְעֵינוֹ. בָּלָק, חֵילוֹ וְכֹחוֹ הָיָה בְּמַעֲשֵׂה יָדַיִם. וְזֶה צָרִיךְ אֶת זֶה, שֶׁהֲרֵי כָּל סוּגֵי הַכְּשָׁפִים שֶׁל הָעוֹלָם, בַּפֶּה וּבְמַעֲשֶׂה הוּא, וּבָהֶם תְּלוּיִים. לְבִלְעָם הָיָה לָשׁוֹן וְלֹא יָדַיִם, לְבָלָק הָיוּ יָדַיִם וְלֹא לָשׁוֹן.</p>\n<p>הָלְכוּ הַחֲבֵרִים עַד שֶׁהִגִּיעוּ לְשָׂדֶה אַחַת, וְהַשֶּׁמֶשׁ הָיְתָה חֲזָקָה מְאֹד. רָאוּ אֶת אוֹתוֹ בֵּית הַשָּׂדֶה בִּיפִי הָעֲשָׂבִים, וּמַיִם יוֹצְאִים לְכָל צַד וַעֲצֵי הַשָּׂדֶה רַבִּים. יָשְׁבוּ שָׁם. אָמַר רַבִּי אֶלְעָזָר, כַּמָּה נָאֶה מָקוֹם זֶה לָנוּחַ בּוֹ.</p>\n<p>עַד שֶׁיָּשְׁבוּ הֲרֵי נָחָשׁ גָּדוֹל בָּא בְּחֹזֶק הַשֶּׁמֶשׁ וְעָבַר לִפְנֵיהֶם. אָמַר לוֹ רַבִּי אֶלְעָזָר, נָחָשׁ נָחָשׁ, סְטֵה לְךְ מִדַּרְכְּךְ, שֶׁהֲרֵי שָׁב אוֹתוֹ הָאִישׁ וְהִתְנַחֵם עַל מַה שֶּׁעָשָׂה וְלֹא יוֹסִיף לַעֲשׂוֹת אוֹתוֹ הַדָּבָר. תָּמְהוּ הַחֲבֵרִים. אָמַר רַבִּי אַבָּא, מַהוּ? אָמַר לָהֶם, שִׁתְקוּ. אָמַר רַבִּי אֶלְעָזָר, נָחָשׁ נָחָשׁ, לְאַחַר שֶׁלָּחֲשׁוּ לְךְ מֵהַשָּׁמַיִם, הִתְנַחֵם אוֹתוֹ הָאִישׁ וְשָׂם בִּרְצוֹנוֹ שֶׁלֹּא יָשׁוּב בּוֹ לְעוֹלָמִים, סְטֵה לְךְ מִדַּרְכְּךְ. עָמַד הַנָּחָשׁ עַל עָמְדוֹ, וְלֹא לָקַח לְכָאן וּלְכָאן. שָׁב כְּמוֹ מִקֹּדֶם. אָמַר לוֹ, נָחָשׁ נָחָשׁ, יָדַעְתִּי מַה שֶּׁאַתָּה רוֹצֶה, שׁוּב מִדַּרְכְּךְ, שֶׁהֲרֵי גּוֹי רָשָׁע בָּא שֶׁעָשָׂה רַע לִיהוּדִי אֶחָד, וַהֲרֵי הוּא יָשֵׁן שׁוֹכֵב בַּמְּעָרָה שֶׁלְּךְ, לֵךְ וְהָרְגֵהוּ. מִיָּד חָזַר אוֹתוֹ הַנָּחָשׁ וְדִלֵּג דִּלּוּגִים לִפְנֵיהֶם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אִם לֹא הָיִיתִי פֹּה, כַּמָּה רָעוֹת הָיָה עוֹשֶׂה הַנָּחָשׁ הַזֶּה, שֶׁהֲרֵי אָדָם יְהוּדִי אֶחָד עָשָׂה מַעֲשֶׂה שֶׁל חֵטְא, וְעַד שֶׁלֹּא שָׁב בִּתְשׁוּבָה לָחֲשׁוּ לַנָּחָשׁ הַזֶּה לַהֲרֹג אוֹתוֹ, וְנִמְלַךְ אוֹתוֹ הָאִישׁ בֵּין כָּךְ וּבֵין כָּךְ, וְהִתְנַחֵם מֵחֶטְאוֹ, וְאָמַר שֶׁלֹּא יָשׁוּב לְעוֹלָמִים לְאוֹתוֹ הַחֵטְא, וְעַל כָּךְ נִצּוֹל מִן הַדִּין.</p>\n<p>אָמְרוּ הַחֲבֵרִים לְרַבִּי אֶלְעָזָר, בַּמֶּה יָדַעְתָּ? אָמַר לָהֶם, סִימָן נָתַן לִי אַבָּא, וַאֲנִי יוֹדֵעַ אוֹתוֹ. אָמַר לוֹ, מֵילָא הַנָּחָשׁ שֶׁיָּדַעְתָּ בּוֹ, אוֹתוֹ שֶׁהִתְנַחֵם וְשָׁב מֵחֶטְאוֹ בַּמֶּה יָדַעְתָּ? אָמַר לָהֶם, כְּשֶׁהָיָה הוֹלֵךְ אוֹתוֹ הַנָּחָשׁ, הַקַּשְׂקַשִּׂים שֶׁלּוֹ הָיוּ עוֹלִים וּזְנָבוֹ זָקוּף, וְהוּא שֶׁהוֹלֵךְ (הולך) בִּבְהִילוּת, רוּחַ אַחַת הָיְתָה הוֹלֶכֶת כְּנֶגְדּוֹ וְקוֹרֵאת לְפָנָיו: שׁוּב מִדַּרְכְּךְ, שֶׁהֲרֵי שָׁב מֵחֶטְאוֹ וְהִתְנַחֵם אוֹתוֹ הָאִישׁ. וְאוֹתוֹ הַנָּחָשׁ הָרַע לֹא הָיָה מְצַיֵּת עַד שֶׁיִּתְּנוּ לוֹ כֹּפֶר אִתּוֹ בִּמְקוֹם אוֹתוֹ אָדָם שֶׁהִתְחַיֵּב מִיתָה וְשָׁב. שֶׁכָּךְ דֶּרֶךְ הַנָּחָשׁ לְמַעְלָה וּלְמַטָּה - כֵּיוָן שֶׁנִּתְּנָה לוֹ רְשׁוּת, לֹא שָׁב עַד שֶׁהִשְׁלִים אוֹתוֹ הַדִּין הָרַע שֶׁנִּתְּנָה לוֹ רְשׁוּת לַעֲשׂוֹת, אוֹ שֶׁיִּתְּנוּ לוֹ בִּמְקוֹמוֹ רָשָׁע אַחֵר בְּכֹפֶר, שֶׁהֲרֵי בְּרֵיקָנוּת הוּא לֹא יֵצֵא, כֵּיוָן שֶׁנִּתְּנָה לוֹ רְשׁוּת.</p>\n<p>אָמְרוּ לוֹ, מֵילָא כָּל זֶה, אוֹתוֹ גּוֹי שֶׁאָמַרְתָּ שֶׁנָּתַתָּ לוֹ כֹּפֶר בַּמֶּה יָדַעְתָּ? אָמַר לָהֶם, כֵּיוָן שֶׁדִּבַּרְתִּי לַנָּחָשׁ, אוֹתוֹ רוּחַ שֶׁהָיְתָה כְּנֶגְדּוֹ וְלוֹחֶשֶׁת לוֹ שֶׁיָּשׁוּב לְדַרְכּוֹ, שֶׁהֲרֵי אוֹתוֹ אָדָם הִתְנַחֵם, דִּלְּגָה אוֹתָהּ רוּחַ עַל אָזְנוֹ (אזני ואמרה לי).</p>\n<p>תָּמְהוּ הַחֲבֵרִים. אָמַר רַבִּי אֶלְעָזָר, נֵלֵךְ וְנִרְאֶה, שֶׁהֲרֵי הַנָּחָשׁ עָשָׂה מַה שֶּׁעָשָׂה. קָמוּ וְקָרְבוּ לְסֶלַע אֶחָד בְּאוֹתוֹ בֵּית שָׂדֶה, וּמָצְאוּ אוֹתוֹ הַגּוֹי מֵת וְאוֹתוֹ נָחָשׁ כָּרוּךְ עַל עֲקֵבוֹ, וְלֹא הָיָה נִבְדָּל מִמֶּנּוּ. וְאַחַר כָּךְ נִפְרַד מֵעֲקֵבוֹ וְעָלָה עַל גְּרוֹנוֹ וְנִכְרַךְ שָׁם, וּמִשָּׁם הָיָה יוֹרֵד עַל עֲקֵבוֹ, שֶׁלֹּא הָיָה נִפְרָד מִמֶּנּוּ.</p>\n<p>מָצְאוּ לוֹ אַרְנָק אֶחָד מָלֵא דִינָרִים שֶׁגָּזַל מִיהוּדִי אֶחָד בַּדֶּרֶךְ וְהִכָּה אוֹתוֹ. לָקַח רַבִּי אֶלְעָזָר אֶת הָאַרְנָק. אָמַר, בָּרוּךְ הָרַחֲמָן שֶׁבַּכֹּל הוּא עוֹשֶׂה שְׁלִיחוּת. שָׁבוּ לְאוֹתוֹ מָקוֹם שֶׁהָיוּ (הולכים).</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, מֵאֲשֶׁר יָקַרְתָּ בְעֵינַי נִכְבַּדְתָּ וַאֲנִי אֲהַבְתִּיךְ וְאֶתֵּן אָדָם תַּחְתֶּיךְ וּלְאֻמִּים תַּחַת נַפְשֶׁךְ (ישעיה מג). מֵאֲשֶׁר יָקַרְתָּ?! יָקָר צָרִיךְ לוֹ לִכְתֹּב! וְכָךְ צָרִיךְ: מֵאֲשֶׁר אַתָּה יָקָר בְּעֵינַי. מַהוּ יָקַרְתָּ? מִכְּלָל שֶׁהוּא מֵעַצְמוֹ הִתְכַּבֵּד, אֶלָּא כָּךְ הוּא בְּוַדַּאי. שֶׁכָּל בֶּן אָדָם שֶׁהוּא בְּחִיּוּב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּהַתְחָלָה הוּא מְזֻלְזָל וּמְתֹעָב (תועבה) לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאַחַר שֶׁנִּמְלַךְ וְשָׁב מֵחֶטְאוֹ, עַכְשָׁו הוּא הִתְכַּבֵּד מֵעַצְמוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא עָלָיו וְאוֹמֵר, מֵאֲשֶׁר יָקַרְתָּ בְעֵינַי נִכְבַּדְתָּ. אַתָּה מֵעַצְמְךְ נִכְבַּדְתָּ.</p>\n<p>בְעֵינַי נִכְבַּדְתָּ וַאֲנִי אֲהַבְתִּיךְ. שֶׁהֲרֵי אֵין אַהֲבָה לַקָּדוֹשׁ-בָּרוּךְ- הוּא עִם הַבֶּן אָדָם בָּעוֹלָם הַזֶּה אֶלָּא בְּמִי שֶׁשָּׁב מֵחֶטְאוֹ, וְעַל זֶה אֲנִי אֲהַבְתִּיךְ, אֲבָל מָה אֶעֱשֶׂה שֶׁהֲרֵי נָתַתִּי רְשׁוּת לַנָּחָשׁ לְהַזִּיק? זוֹהִי הָעֵצָה - וְאֶתֵּן אָדָם תַּחְתֶּיךְ. מַהוּ אָדָם שֶׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא תַּחְתָּיו? אוֹתוֹ אָדָם שֶׁבָּא מֵעַם אַחֵר, שֶׁאוֹתוֹ נָחָשׁ יֹאכַל מִשֶּׁלּוֹ, שֶׁכָּתוּב וְאֶתֵּן אָדָם, אַל תִּקְרֵי אָדָם אֶלָּא אֱדוֹם. וּלְאֻמִּים, זֶהוּ (בראשית כה) לְאֹם מִלְאֹם יֶאֱמָץ, וְזֶה זֶרַע עֵשָׂו שֶׁנָּתַן תַּחַת נַפְשׁוֹ.</p>\n<p>עַד שֶׁיָּשְׁבוּ הֲרֵי הַיְּהוּדִי הַזֶּה שֶׁאוֹתוֹ הַגּוֹי גָּזַל וְהַנָּחָשׁ הֲרָגוֹ, בָּא בַדֶּרֶךְ לֵאֶה וְעָיֵף, וּמִתּוֹךְ חֹזֶק הַשֶּׁמֶשׁ נִכְנַס בְּאוֹתוֹ שָׂדֶה וְיָשַׁב תַּחַת עֵץ אֶחָד, וְהָיָה מִתְרַעֵם לַקָּדוֹשׁ-בָּרוּךְ-הוּא וּמַצְדִּיק עָלָיו אֶת הַדִּין וְאוֹמֵר: רִבּוֹן הָעוֹלָם, גָּלוּי וְיָדוּעַ לְפָנֶיךְ שֶׁאֵינִי חוֹשֵׁשׁ עָלַי וְעַל גּוּפִי וְעַל מָמוֹנִי כְּלוּם, שֶׁהֲרֵי בְּדִין נַעֲשָׂה כָּל (מה) שֶׁנַּעֲשָׂה, אֲבָל אָב וָאֵם זְקֵנִים יֵשׁ לִי, שֶׁאֵין לִי בַּמָּה אֲפַרְנֵס אוֹתָם, וְעַל זֶה חָשַׁשְׁתִּי.</p>\n<p>וְעוֹד עַל כָּל זֶה - צְרוֹר אֶחָד שֶׁל דִּינָרִים שֶׁהָיָה בְּאוֹתוֹ הָאַרְנָק, שֶׁל עָנִי אֶחָד לַעֲשׂוֹת חֻפָּה לְבִתּוֹ הָעֲנִיָּה, מָה אֶעֱשֶׂה? רִבּוֹן הָעוֹלָם, עַל זֶה כּוֹאֲבַנִי בְּלִבִּי יוֹתֵר.</p>\n<p>בָּכָה וְאָמַר, (תהלים יט) מִשְׁפְּטֵי ה' אֱמֶת צָדְקוּ יַחְדָּו. דִּינָיו שֶׁל רִבּוֹן הָעוֹלָם הֵם אֱמֶת. לָמָּה הֵם אֱמֶת? מִשּׁוּם שֶׁצָּדְקוּ יַחְדָּו. שֶׁהֲרֵי בִּשְׁעַת הַדִּין, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לַעֲשׂוֹת (דין), כַּמָּה בַּעֲלֵי מָגִנִּים עוֹמְדִים מִצַּד זֶה וּמִצַּד זֶה, וּמַצְדִּיקִים אֵלּוּ בְאֵלּוּ, וְנִלְחָמִים אֵלּוּ בְאֵלּוּ. כֵּיוָן שֶׁצָּדְקוּ אֵלּוּ בְאֵלּוּ וְהִסְכִּימוּ כְאֶחָד, אֲזַי מִשְׁפְּטֵי ה' אֱמֶת. אֵימָתַי צָדְקוּ יַחְדָּו? כְּשֶׁמַּצְדִּיקִים כָּל בְּנֵי הַדִּין שֶׁלְּמַעְלָה. וְעַל זֶה, רִבּוֹן הָעוֹלָם, אֲנִי בּוֹכֶה, וְלֹא עַל שֶׁלִּי!</p>\n<p>שָׁמַע רַבִּי אֶלְעָזָר וְהַחֲבֵרִים, וְקָמוּ אֵלָיו. רָאוּ אוֹתוֹ שֶׁהָיָה יוֹשֵׁב תַּחַת אוֹתוֹ הָעֵץ, וְהֶחֱזִיקוּ בוֹ, וְנָטְלוּ אוֹתוֹ אֲלֵיהֶם. אָמַר רַבִּי אֶלְעָזָר, (אל תפחד) צַדִּיק אֱמֶת, שֶׁאִם אֵינְךְ צַדִּיק, לֹא יַרְחִישׁ לְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא נֵס גָּדוֹל כְּמוֹ שֶׁעָשָׂה. בָּרִאשׁוֹנָה טֹל אַרְנָקְךְ, וְתֵלֵךְ וְתִרְאֶה מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּגְלָלְךְ. הָלַךָ עִמָּם, וְרָאָה אוֹתוֹ הַגּוֹי מֵת, וְהַנָּחָשׁ הָיָה עוֹשֶׂה בּוֹ נְקָמוֹת, וְהָיָה כָּרוּךְ עַל צַוָּארוֹ. הִשְׁתַּטַּח אוֹתוֹ הַיְּהוּדִי בֶּעָפָר, וְהוֹדָה וְשִׁבַּח אֶת רִבּוֹן הָעוֹלָם, וְקָם וְנָשַׁק יְדֵי רַבִּי אֶלְעָזָר וְהַחֲבֵרִים. אָמַר לָהֶם: כָּעֵת יָדַעְתִּי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִרְחִישׁ נֵס זֶה בִּגְלַלְכֶם.</p>\n<p>אֲבָל חֲכָמִים, עַל הָאָב וְהָאֵם הַזְּקֵנִים שֶׁיֵּשׁ לִי אֲנִי בּוֹכֶה, וְעַל הֶעָנִי שֶׁנָּתַן לִי אֶת הַצְּרוֹר. פָּתַח הָאַרְנָק וְהֶרְאָה לָהֶם אֶת הַצְּרוֹר, וְכֵן הֶרְאָה לָהֶם הַמַּכָּה שֶׁעָשָׂה לוֹ אוֹתוֹ הַגּוֹי. הִתְפַּלֵּל עָלָיו רַבִּי אֶלְעָזָר, וְנִרְפָּא.</p>\n<p>קָרְבוּ לְאוֹתוֹ הַגּוֹי כְּמִקֹּדֶם, וְרָאוּ אוֹתוֹ הַנָּחָשׁ שֶׁהָיָה עוֹשֶׂה בּוֹ כְּבָרִאשׁוֹנָה. אָמַר רַבִּי אֶלְעָזָר, נָחָשׁ נָחָשׁ, כָּל מַה שֶּׁעָשִׂיתָ - נָאֶה עָשִׂיתָ, וְעוֹד שֶׁהֶרְאֵיתָ כֹּחֲךְ וּגְבוּרָתְךְ בּוֹ וְעָשִׂיתָ בּוֹ נְקָמוֹת רַבּוֹת, וַהֲרֵי רָאִינוּ שָׁלֹשׁ פְּעָמִים, וְהֶרְאֵיתָ כָּל מַה שֶּׁעָשִׂיתָ. מִכָּאן וָהָלְאָה לֵךְ וְהִתְחַבֵּא בִּמְעָרָתְךְ, וְגוֹזְרַנִי עָלֶיךְ, שֶׁלֹּא תַזִּיק לִבְרִיָּה בָּעוֹלָם. נִפְרַד אוֹתוֹ הַנָּחָשׁ, וְכָפַף רֹאשׁוֹ וְהָלַךְ לוֹ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר לְאוֹתוֹ הַיְּהוּדִי: טֹל אֶת תַּכְשִׁיט שׂוֹנַאֲךְ, שֶׁהֲרֵי כִּיס שֶׁל זָהָב יֵשׁ לוֹ אֶצְלוֹ שֶׁהִשְׁאִיר לוֹ בְּנוֹ שֶׁל אוֹתוֹ גּוֹי לְאָבִיו, וְאַל תִּטֹּל מִשֶּׁלּוֹ כְּלוּם, וְלֵךְ לָאִישׁ שֶׁבְּמָקוֹם פְּלוֹנִי, וְתִמְצָא שֶׁמֵּתָה אִשְׁתּוֹ. לֵךְ אֵלָיו, וְתֵן לוֹ כִּיס הַדִּינָרִים הַזֶּה, מִשּׁוּם שֶׁלְּאוֹתוֹ הָאִישׁ יֵשׁ בֵּן אֶחָד, וּשְׁמוֹ שִׁמְעוֹן, וְהָיָה הוֹלֵךְ עִם סְחוֹרָה עַל הַיָּם, וְהֵם בַּסְּפִינָה, וּבְנוֹ שֶׁל הַגּוֹי הַזֶּה גָּנַב לוֹ אוֹתוֹ הַכִּיס וְנָתַן אוֹתוֹ לְאוֹתוֹ רָשָׁע. וֶאֱמֹר לְאוֹתוֹ הַיְּהוּדִי שֶׁיַּעֲלֶה כִיס זֶה לִבְנוֹ, שֶׁבִּמְהִירוּת יֵלֵךְ אֵלָיו, וְיוֹדֶה לַקָּדוֹשׁ-בָּרוּךְ- הוּא שֶׁהֶחֱזִיר אֲבֵדָה לִבְעָלָיו. וְכָךְ עָשָׂה. נָטַל הַכִּיס, וְהִשְׁתַּחֲוָה לִפְנֵי רַבִּי אֶלְעָזָר וְנָשַׁק יָדוֹ. תָּמְהוּ הַחֲבֵרִים.</p>\n<p>אָמַר רַבִּי אַבָּא, בְּכָל הַדֶּרֶךְ הַזּוֹ יֵשׁ תְּמִיהָה בְּכָל מַה שֶּׁרָאִינוּ בְּךְ, וְכָעֵת הִיא תְמִיהָה עַל תְּמִיהָה, מַה זֶּה? אָמַר לָהֶם: דָּבָר זֶה אֵינוֹ בְסִימָן הוּא וְלֹא בְחָכְמָה, אֶלָּא שֶׁרוּחִי מִסְתַּכֵּל, וַאֲנִי רָאִיתִי כְּאִלּוּ בָּעַיִן רָאִיתִי. תָּמְהוּ כָּל הַחֲבֵרִים. הָלְכוּ כָּל הַחֲבֵרִים וְאוֹתוֹ הַיְּהוּדִי עִמָּהֶם, עַד שֶׁהִגִּיעוּ לְחָמִיו. כֵּיוָן שֶׁהִגִּיעוּ לְשָׁם, מָצְאוּ אֶת חָמִיו שֶׁהָיָה יוֹשֵׁב עַל גַּבֵּי מִטָּתוֹ וְעוֹסֵק בַּתּוֹרָה. בֵּרַךְ בְּרָכָה רַבִּי אֶלְעָזָר, וּבֵרְכוּ הַחֲבֵרִים, וְהוּא שָׂמַח עִמָּם.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (ירמיה יז) רְפָאֵנִי ה' וְאֵרָפֵא הוֹשִׁיעֵנִי וְאִוָּשֵׁעָה. כֵּיוָן שֶׁאָמַר רְפָאֵנִי ה', מַהוּ וְאֵרָפֵא? כֵּיוָן שֶׁאָמַר הוֹשִׁיעֵנִי, מַהוּ וְאִוָּשֵׁעָה? כֵּיוָן שֶׁהָרוֹפֵא מְרַפֵּא, מִי הוּא שֶׁיַּכֶּה?</p>\n<p>אֶלָּא (אמר רבי יוסי חמיו), כָּל רְפוּאָה שֶׁבָּעוֹלָם בְּיַד הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲבָל יֵשׁ מֵהֶם עַל יְדֵי שָׁלִיחַ, וְיֵשׁ מֵהֶם שֶׁלֹּא נִמְסְרוּ בְּיַד שָׁלִיחַ. וְאוֹתָם שֶׁנִּמְסְרוּ בְּיַד שָׁלִיחַ הֵם רְפוּאָה, אֲבָל לִפְעָמִים חוֹזְרִים. אֲבָל אוֹתָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְרַפֵּא לֹא חוֹזְרִים לְעוֹלָמִים, וְעַל זֶה רְפוּאָתוֹ הִיא רְפוּאָה, שֶׁאֵין בָּהּ חֹלִי כְּלָל. וּמִשּׁוּם כָּךְ רְפָאֵנִי ה' וְאֵרָפֵא, וְזֶה בְּלִי קִטְרוּג כְּלָל. וְכָעֵת, חֲבֵרִים, הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לִי רְפוּאָה, וְעָשַׁק לִי וְעָרַב לִי.</p>\n<p>סִפְּרוּ לוֹ כָּל אוֹתוֹ הַמַּעֲשֶׂה. תָּמַהּ וּבָכָה וְשָׂמַח. אָמַר, חֲבֵרִים, נָדַרְתִּי שֶׁאֵלֵךְ אֵלָיו וְאֶתְחַבֵּר עִמּוֹ, וְנוֹדֶה וּנְשַׁבַּח לְרִבּוֹן הָעוֹלָם. שָׂמַח עִמָּם.</p>\n<p>אָמְרוּ לוֹ: בַּמָּה הָיִיתָ מִתְעַסֵּק? אָמַר לָהֶם, הָיִיתִי מִתְעַסֵּק בְּפָרָשַׁת בָּלָק, וְרָאִיתִי שֶׁחָכְמָתוֹ הָיְתָה חֲזָקָה וְיוֹתֵר מֵחָכְמָתוֹ שֶׁל בִּלְעָם. חָכְמַת בִּלְעָם פַּעַם אַחַת - וְחָכְמַת בָּלָק בְּכָל זְמַן. אֲבָל כָּל הַמַּפְתְּחוֹת הָיוּ בִּידֵי בִלְעָם, מִשּׁוּם שֶׁהוּא הָיָה שָׁלֵם בַּפֶּה. בָּלָק הָיָה יוֹדֵעַ לַעֲשׂוֹת כְּשָׁפָיו, וְלֹא יָדַע לְהַשְׁלִים בַּפֶּה.</p>\n<p>פָּתַח וְאָמַר, (שם מו) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב כוּ'. הַפָּסוּק הַזֶּה (יש להסתכל בו) פֵּרְשׁוּהוּ. אֲבָל אַל תִּירָא עַבְדִּי יַעֲקֹב - מֵהַכְּשָׁפִים שֶׁל בִּלְעָם. וְאַל תֵּחַת - מֵהַקְּסָמִים שֶׁל בָּלָק.</p>\n<p>בֹּא וּרְאֵה אֵיךְ הָיוּ שְׁנֵיהֶם זֶה עִם זֶה בְּעֵצָה רָעָה כְּנֶגֶד יִשְׂרָאֵל. אָמַר בִּלְעָם: יַעֲקֹב הָיָה בְּבֵית לָבָן אַבָּא, וְנִחֵשׁ נְחָשִׁים כְּנֶגְדּוֹ וְיָכֹל לוֹ, אֲנִי אֲסַדֵּר נְחָשִׁים כְּנֶגְדּוֹ. אָמַר בָּלָק: וַאֲנִי אֲסַדֵּר קְסָמִים לַשֵּׁם שֶׁנִּקְרָא יִשְׂרָאֵל.</p>\n<p>בְּאוֹתָהּ שָׁעָה יָצְאָה רוּחַ אַחַת מִצִּדּוֹ שֶׁל יוֹסֵף מִתּוֹךְ עַנְפֵי הָאִילָן, וְנָשְׁבָה בְּאוֹתָם נְחָשִׁים וּבִטְּלָתָם, וְהַיְנוּ שֶׁאָמַר יוֹסֵף (בראשית מד) כִּי נַחֵשׁ יְנַחֵשׁ אִישׁ אֲשֶׁר כָּמֹנִי. מַה זֶּה אִישׁ אֲשֶׁר כָּמֹנִי? בִּשְׁבִילִי יֵשׁ אִישׁ שֶׁיְּבַטֵּל הַנְּחָשִׁים לִבְנֵיכֶם. בִּשְׁבִילִי הוּא לְמַעְלָה, וְהַיְנוּ אִישׁ אֲשֶׁר כָּמֹנִי. כָּמוֹנִי יֵשׁ אִישׁ לְמַעְלָה שֶׁמּוֹצִיא רוּחַ אַחֶרֶת מִתּוֹךָ הָעֵץ שֶׁלְּמַטָּה, וְנָשַׁב בְּאוֹתוֹ הַקֶּסֶם וּבִטֵּל אוֹתוֹ.</p>\n<p>וְהַיְנוּ (משליטז) קֶסֶם עַל שִׂפְתֵי מֶלֶךָ. מִי הַמֶּלֶךָ? זֶה הָעֵץ שֶׁלְּמַטָּה. אֲזַי הֵשִׁיב בִּלְעָם וְאָמַר, (במדבר כג) כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל. וּשְׁנֵיהֶם הָיוּ מִשְּׁנֵי הַצְּדָדִים הַלָּלוּ.</p>\n<p>כִּי אִתְּךְ אָנִי. לֹא הָיוּ יָמִים מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם שֶׁהִצְטָרֵךָ לִהְיוֹת כָּךָ הַקָּדוֹשׁ בָּרוּךָ הוּא עִם יִשְׂרָאֵל כְּאוֹתוֹ הַזְּמַן שֶׁרָצָה בִּלְעָם לְכַלּוֹת אֶת שׂוֹנְאֵי יִשְׂרָאֵל מִן הָעוֹלָם. וְעַל זֶה אָמַר הַקָּדוֹשׁ בָּרוּךָ הוּא: בִּלְעָם רָצָה לְהַשְׁמִידְכֶם מִן הָעוֹלָם, אֲבָל אֲנִי לֹא אֶעֱשֶׂה כָּךָ, (ירמיה מו) כִּי אֶעֱשֶׂה כָלָה בְּכָל הַגּוֹיִם אֲשֶׁר הִדַּחְתִּיךְ שָּׁמָּה וְאֹתְךְ לֹא אֶעֱשֶׂה כָלָה. שֶּׁאִלּוּ יָבֹאוּ כָּל עַמֵּי הָעוֹלָם, לֹא יְכוֹלִים לְהַשְׁמִידְכֶם מִן הָעוֹלָם.</p>\n<p>בָּא לָבָן בָּרִאשׁוֹנָה וְרָצָה לַעֲקֹר אֶת יַעֲקֹב לְבַדּוֹ מִן הָעוֹלָם - בָּא הַקָּדוֹשׁ בָּרוּךָ הוּא וְהֵגֵן עָלָיו, שֶׁכָּתוּב (בראשית לא) הִשָּׁמֶר לְךְ פֶּן תְּדַבֵּר עִם יַעֲקֹב מִטּוֹב עַד רָע. בָּא פַּרְעֹה וְרָצָה לְהַשְׁמִידָם מִן הָעוֹלָם - בָּא הַקָּדוֹשׁ בָּרוּךָ הוּא וְהֵגֵן עֲלֵיהֶם, שֶׁכָּתוּב (שמות א) וְכַאֲשֶׁר יְעַנּוּ אֹתוֹ כֵּן יִרְבֶּה וְכֵן יִפְרֹץ. בָּא הָמָן וְרָצָה לְהַשְׁמִידָם - בָּא הַקָּדוֹשׁ בָּרוּךָ הוּא וְהֵגֵן עֲלֵיהֶם וְהֵשִׁיב הַכֹּל עַל רֹאשׁוֹ. וְכֵן בְּכָל דּוֹר וָדוֹר הַקָּדוֹשׁ בָּרוּךָ הוּא הֵגֵן עַל יִשְׂרָאֵל תָּמִיד.</p>\n<p>וְיִשְּׂרָאֵל אוֹמְרִים, (איכה ג) חַסְדֵי ה' כִּי תָמְנוּ כִּי לֹא כָלוּ רַחֲמָיו. כִּי לֹא תַמּוּ הָיָה צָרִיךָ לִכְתֹּב! אֶלָּא חַסְדֵי ה' בְּכָל דּוֹר וָדוֹר הָיוּ בְעֶזְרֵנוּ כִּי לֹא תַמְנוּ וְלֹא הֻשְׁמַדְנוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא נִמְנְעוּ רַחֲמָיו מֵעִמָּנוּ, שֶׁכָּתוּב (שם) כִּי לֹא כָלוּ רַחֲמָיו.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב בָּרִאשׁוֹנָה, (במדבר כב) וַיִּשְׁלַח מַלְאָכִים אֶל בִּלְעָם בֶּן בְּעוֹר, וְאַחַר כָּךָ וַיֵּלְכוּ זִקְנֵי מוֹאָב וְזִקְנֵי מִדְיָן. הָיָה לוֹ לוֹמַר וַיָּבאוּ הַמַּלְאָכִים, מָה הַטַּעַם שִׁנָּה הַדָּבָר מִמַּה שֶּׁאָמַר בָּרִאשׁוֹנָה?</p>\n<p>אֶלָּא, אוֹתוֹ בָּלָק הָרָשָׁע הָיָה חָכָם בְּכָל הַדְּרָגוֹת שֶׁלְּמַעְלָה, אוֹתָם שֶׁקּוֹשְׁרִים קְשָׁרִים לַעֲשׂוֹת בָּהֶם כְּשָׁפִים וּקְסָמִים, וְכָל אוֹתָן דְּרָגוֹת יוֹתֵר עֶלְיוֹנוֹת (מהן) דִּבְרֵיהֶם, שֶׁבָּהֶן כּוֹפִים אֶת הַדְּרָגוֹת הַתַּחְתּוֹנוֹת.</p>\n<p>אָמַר לוֹ, בְּכָל פַּעַם שֶׁאָנוּ מְכַשְּׁפִים וְקוֹסְמִים וּמְנַחֲשִׁים, יֵשׁ לָנוּ דְּרָגוֹת וּמַלְאָכִים יְדוּעִים, שֶׁנּוֹדָעִים לַמְּכַשְּׁפִים וְלַקּוֹסְמִים, אֲבָל מִכָּאן וָהָלְאָה יֵשׁ לְךְ לְעַיֵּן בְּמָקוֹם אַחֵר עֶלְיוֹן.</p>\n<p>כָּתַב לוֹ שֵׁמוֹת אֲחֵרִים בְּאוֹתָן דְּרָגוֹת קְדוֹשׁוֹת. וְכָךְ דַּרְכֵי הַקּוֹסְמִים וְהַמְּכַשְּׁפִים, שֶׁיּוֹדְעִים אוֹתָן דְּרָגוֹת שֶׁאוֹתוֹ קֶסֶם שׁוֹרֶה בָהֶם, וְעוֹשִׂים כִּשְׁפֵיהֶם, וּמַשְׁבִּיעִים אוֹתָם בִּדְרָגוֹת אֲחֵרוֹת עֶלְיוֹנוֹת מֵהֶם, וְעוֹשִׂים מַה שֶּׁעוֹשִׂים.</p>\n<p>שָׁלַח לוֹ כָּךְ: הָעָם הַזֶּה, אֵין הַקֶּשֶׁר שֶׁלָּהֶם כִּשְׁאָר עַמֵּי הָעוֹלָם, אֲבָל הַקֶּשֶׁר שֶׁלָּהֶם בְּמָקוֹם אַחֵר עֶלְיוֹן נִקְשָׁרִים מֵעַל לְכָל הַדְּרָגוֹת.</p>\n<p>כָּתַב וְשָׁלַח לוֹ שְׁמוֹת הַהִשְׁתַּלְשְׁלוּת וְהָאֲבָהוּת שֶׁל שְׁנֵים עָשָׂר נִיצוֹצוֹת (נשיאים) שֶׁסּוֹבְבִים גַּלְגַּלֵּי הַמֶּרְכָּבָה שֶׁל הַכִּסֵּא הַקָּדוֹשׁ. אָמַר לוֹ: אִם תִּסְתַּכֵּל, בְּאֵלּוּ תִּסְתַּכֵּל, מִשּׁוּם שֶׁהַשְּׁנֵים עָשָׂר הַלָּלוּ שֶׁנִּקְשָׁרִים בִּשְׁנֵים עָשָׂר שְׁבָטִים. וְאִם בְּאֵלֶּה תַּעֲשֶׂה כְשָׁפִים, בַּדְּיוֹקָן שֶׁלָּהֶם לְמַטָּה, שֶׁהֵם שְׁנֵים עָשָׂר שְׁבָטִים וּשְׁנֵים עָשָׂר דְּגָלִים פְּרוּשִׂים, נוּכַל לָהֶם, וְנִלָּחֵם בָּהֶם בִּקְרָב, וְנַעֲקֹר אוֹתָם מִן הָעוֹלָם.</p>\n<p>וְהַיְנוּ וַיִּשְׁלַח מַלְאָכִים וַדַּאי. זֶהוּ שֶׁכָּתוּב וּקְסָמִים בְּיָדָם, שְׁמוֹת הַהִשְׁתַּלְשְׁלוּת שֶׁל מַלְאָכִים קְדוֹשִׁים הָיוּ מְבִיאִים בִּידֵיהֶם. וְהוּא לֹא יָדַע שֶׁכָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת הֵם בִּידֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. מֶה חָשַׁב בָּלָק? חָשַׁב שֶׁעַם יִשְׂרָאֵל נִמְסְרוּ לַמַּלְאָכִים כִּשְׁאָר הָעַמִּים שֶׁל הָעוֹלָם, וְעַל כֵּן כָּתַב שֵׁמוֹת שֶׁל שְׁנֵים עָשָׂר הַמַּלְאָכִים הַלָּלוּ וְשָׁלַח לוֹ, וְהַיְנוּ וַיִּשְׁלַח מַלְאָכִים.</p>\n<p>אָמַר לוֹ: בּא וּרְאֵה, כָּל הַדְּרָגוֹת שֶׁקּוֹשְׁרוֹת קְשָׁרִים לִשְׁבֹּר אֶת הָעָם הַזֶּה, הֵן מִצַּד הַצָּפוֹן, וּמִצַּד הַצָּפוֹן עֲתִידִים לִפֹּל, וְשִׁלְטוֹן הַמְכַשְּׁפִים שֶׁלָּנוּ הֵם מִצַּד הַצָּפוֹן. עַכְשָׁו נוּכַל לְהִלָּחֵם בָּהֶם בַּקְּרָב, שֶׁהֲרֵי שְׁנֵים עָשָׂר הַלָּלוּ (שהם) קְשׁוּרִים בָּהֶם, וּמִצַּד הַצָּפוֹן מַתְחִילִים לְהִמָּנוֹת.</p>\n<p>וְהוֹאִיל וּמִשְּׂמֹאל מַתְחִיל, הַתֹּקֶף שֶׁלָּהֶם נֶחֱלָשׁ וְנִשְׁבָּר, מִשּׁוּם שֶׁכָּל תָּקְפָּם הוּא לְאוֹתוֹ הַצַּד. מַהוּ שֶׁאָמַר שֶׁכָּתוּב (מלכים א ז) עֹמֵד עַל שְׁנֵי עָשָׂר בָּקָר שְׁלֹשָׁה פֹנִים צָפוֹנָה, מִצָּפוֹן מַתְחִיל לִמְנוֹת? אָמַר, הִנֵּה הַתֹּקֶף שֶׁלָּנוּ הוּא מִצָּפוֹן, וְאוֹתָן אַרְבָּעִים חָסֵר אַחַת, דְּרָגוֹת חֲזָקוֹת מִבַּרְזֶל וּנְחֹשֶׁת, וְשֶׁתַּחְתֵּיהֶן אֵין לָהֶן חֶשְׁבּוֹן, וְעַל כֵּן נוּכַל לַעֲרֹךְ בָּהֶם קְרָב וּלְהִתְגָּרוֹת בָּהֶם.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא לֹא עָשָׂה כָּךְ, שֶׁלֹּא הִשְׁאִיר אוֹתָם לַמַּלְאָכִים וְלֹא לְצִבְאוֹת הַשָּׁמַיִם, אֶלָּא לַקָּדוֹשׁ-בָּרוּךְ-הוּא לְבַדּוֹ. וְכָל הַמַּלְאָכִים הַגְּדוֹלִים וְהַשַּׁלִּיטִים חִלֵּק אוֹתָם עַל כָּל שְׁאָר הָעַמִּים. וּכְשֶׁבָּאוּ יִשְׂרָאֵל, נָטַל אוֹתָם הוּא לְבַדּוֹ, וְהִנְחִיל אוֹתָם בְּתֹקֶף בְּגוּף הָאִילָן, וְלֹא עָזַב אוֹתָם בְּיַד הַמַּלְאָכִים, וְלֹא בְּיַד מְמֻנִּים וּגְדוֹלִים שֶׁל הָעוֹלָם, שֶׁכָּתוּב (דברים לב) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם. וְאֵלּוּ שְׁנֵים עָשָׂר תְּחוּמִים מְתֻחָמִים בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם, אַחַר שֶׁפִּזֵּר עֲנָפִים וְעָלִים, נָטל אֶת יִשְׂרָאֵל וְהִנְחִיל אוֹתָם בְּתקֶךְ גּוּךְ הָאִילָן, שֶׁכָּתוּב (שם) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, כַּמָּה יָפֶה וְנָאֶה זֶהָ. אַשְׁרֵי דַּרְכֵּנוּ, וְכַמָּה דְבָרִים עֶלְיוֹנִים קְדוֹשִׁים הִרְוַחְנוּ אוֹתָם וְרָאִיתִי. וְאוֹתוֹ יְהוּדִי הָיָה שָׁם לִפְנֵיהֶם. אָמַר לָהֶם, חֲכָמִים, כָּל הַדְּבָרִים הַלָּלוּ כַּמָּה טוֹבִים, וּדְבָרִים עֶלְיוֹנִים קְדוֹשִׁים הֵם. מַה זֶּה שֶׁכָּתוּב אַחֲרָיוִ (שם) יִמְצָאֵהוִּ בְּאֶרֶץ מִדְבָּר וּבְתהוּ יְלֵל יְשִׁמן וְגוֹ'?</p>\n<p>אָמַר לוֹ, אִם יָדַעְתָּ בּוֹ דָּבָר - אֱמר, שֶׁהֲרֵי הַדָּבָר הַזֶּה פֵּרְשׁוּהוּ בְּאַבְרָהָם, שֶׁמָּצָא אוֹתוֹ הַקָּדוֹשׁ בָּרוּךָ הוּא בְּאֶרֶץ שֶׁעוֹבְדִים עֲבוֹדָה זָרָה, וְאֵין מַכִּירִים אֶת אֱמוּנַת הַקָּדוֹשׁ בָּרוּךָ הוּא, אֶלָּא כֻּלָּם הָיוּ טוֹעִים אַחַר עֲבוֹדָה זָרָה, וְקָם אַבְרָהָם, וְהִפְרִיחַ בֵּינֵיהֶם עָנָךְ אֶחָד שָׁלֵם לִפְנֵי רִבּוֹן הָעוֹלָם, וּמָצָא אוֹתוֹ שָׁם.</p>\n<p>מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךָ הוּא? נָטַל אֶת אוֹתוֹ הֶעָנָךְ וְעָקַר אוֹתוֹ מִשָּׁם, וְהִשְׁרָה אוֹתוֹ וְהִשְׁתַּדֵּל וְשָׁתַל אוֹתוֹ בְּאֶרֶץ אַחֶרֶת, שֶׁכָּתוּב (בראשית יב) לֶךָ לְךְ מֵאַרְצְךְ וְגוֹמֵר, וְעָשָׂה מִמֶּנּוּ עַם קָדוֹשׁ, וְזוֹ הַמְּצִיאָה שֶׁמָּצָא הַקָּדוֹשׁ בָּרוּךָ הוּא בָּעוֹלָם, בְּאֶרֶץ שֶׁלֹּא מַאֲמִינִים בַּקָּדוֹשׁ-בָּרוּךָ-הוּא וְלֹא יוֹדְעִים מִי הוּא.</p>\n<p>אָמַר אוֹתוֹ יְהוּדִי, יָפֶה זֶה, וְנָאֶה דָבָר זֶה, אֲבָל יֵשׁ לִשְׁאל אִם אַבְרָהָם הָיָה דְיוֹקָן שֶׁהֻצְרַךָ? וְעוֹד, שֶׁהֲרֵי הַכָּתוּב לֹא מוֹכִיחַ עַל אַבְרָהָם כְּלָל, וְלֹא הִזְכִּיר אֶת אַבְרָהָם כְּלָל, וְלֹא אֶת יִצְחָק, אֶלָּא אֶת יַעֲקֹב לְבַדּוֹ, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ, וְאַחַר כָּךָ כָּתוּב יִמְצָאֵהוּ וְגוֹמֵר.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, עִם כָּל זֶה לֹא קָשֶׁה כָּאן, שֶׁהֲרֵי מָצָאנוּ שֶׁאַבְרָהָם יָצָא מִתּוֹךָ עוֹבְדֵי עֲבוֹדָה זָרָה, וְכָאן - אַף עַל גַּב שֶׁיַּעֲקֹב נִזְכָּר, הוּא מְדַבֵּר עַל אַבְרָהָם, וְאֵין כְּלָל קֻשְׁיָה בְּדָבָר זֶה. אֲבָל אִם יָדַעְתָּ דָּבָר אוֹ חִדּוּשׁ - אֱמֹר. ע\"כ מההשמטות.</p>"],[9522012744,"<p>פָּתַח אוֹתוֹ יְהוּדִי וְאָמַר, (בראשית א) וְהָאָרֶץ הָיְתָה תֹהוּ וָבהוּ וְגוֹמֵר. מִי הָאָרֶץ? אוֹתָהּ הַנּוֹדַעַת לְמַעְלָה וּמַטָּה. הָיְתָה תֹהוּ, מַה זֶּה תֹּהוּ? זֶה קַו יָרֹק שֶׁמַּקִּיף אֶת כָּל הָעוֹלָם, וְנִקְרָא קַו תֹהוּ, שֶׁכָּתוּב (ישעיה לד) וְנָטָה עָלֶיהָ קַו תֹהוּ וְאַבְנֵי בהוּ. בהוּ, כְּמוֹ שֶׁשָּׁנִינוּ, אֲבָנִים מְפֻלָּמוֹת שֶׁמְּשֻׁקָּעוֹת בְּתוֹךְ הַתְּהוֹמוֹת, וּמֵהֶן יוֹצְאִים מַיִם.</p>\n<p>עַכְשָׁו יֵשׁ לָדַעַת, תֹּהוּ, שֶׁהוּא קַו יָרֹק, מַהוּ קַו יָרֹק? אֶלָּא מָצָאנוּ בְּסֵפֶר הָרוֹפֵא מִקַּרְטִינָאָה, וְיוּדָן שֶׁל קֵסָרִי שְׁמוֹ, וְקוֹרְאִים אֶת שְׁמוֹ הָרוֹפֵא הַקַּרְטִינָאִי, מִשּׁוּם שֶׁהוּא גָּדוֹל עַל כָּל הָרוֹפְאִים וְנִכְבָּד בְּחָכְמָה. וְכָךְ אוֹמְרִים בְּלָשׁוֹן פַּרְסִי לְאָדָם נִכְבָּד. וְהוּא הָיָה אוֹמֵר, וְהָאָרֶץ הָיְתָה תֹהוּ, מַה זֶּה תֹּהוּ? הוּא קַו יָרֹק שֶׁמַּקִּיף כָּל הָעוֹלָם, וּמִי הוּא? קְלִפַּת הָאֱגוֹז, וְזוֹהִי הַקְּלִפָּה הַחִיצוֹנָה, שֶׁהִיא יְרֻקָּה.</p>\n<p>לִפְנִים מִמֶּנּוּ - בּהוּ, וְהֵן אֲבָנִים מְפֻלָּמוֹת שֶׁמֵּהֶן יוֹצְאִים מַיִם. מִתֹּהוּ נִמְשָׁךְ עוֹר וּבָשָׂר. מִן בֹּהוּ נִמְשָׁכוֹת הָעֲצָמוֹת. לִפְנִים מִמֶּנּוּ - וְחֹשֶׁךְ. זוֹ הַהַמְשָׁכָה שֶׁנִּמְשָׁךְ מִמֶּנָּה הָעָם שֶׁל עֵשָׂו. וְאִם תֹּאמַר מַה זֶּה תֹּהוּ? הֲרֵי הִיא בְּוַדַּאי שֶׁהֲרֵי הַחֹשֶׁךְ תָּלוּי מִמֶּנּוּ, אֶלָּא אוֹתָן אֲבָנִים מְפֻלָּמוֹת נִכְנְסוּ בָּאֶמְצַע, שֶׁמִּמֶּנּוּ נִמְשָׁכוֹת הָעֲצָמוֹת, כְּמוֹ שֶׁנֶּאֱמַר. וְחֹשֶׁךְ - מְשִׁיכָה דַקָּה, שֶׁמִּמֶּנָּה נִמְשָׁךְ עֵשָׂו.</p>\n<p>וְרוּחַ אֱלֹהִים - זֶה מֹחַ הָאֱגוֹז, שֶׁמִּשָּׁם נִמְשָׁךְ יַעֲקֹב הַשָּׁלֵם, כְּמוֹ הָאֱגוֹז הַזֶּה, סוֹד הַכָּתוּב (יחזקאל א) וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן, כְּנֶגֶד הַתֹּהוּ. לִפְנִים מִמֶּנּוּ - עָנָן גָּדוֹל, כְּנֶגֶד הַבּהוּ. לִפְנִים מִמֶּנּוּ - וְאֵשׁ מִתְלַקַּחַת, כְּנֶגֶד הַחֹשֶׁךְ. לִפְנִים מִמֶּנּוּ - וְנֹגַהּ לוֹ סָבִיב, כְּנֶגֶד שֶׁל וְרוּחַ אֱלֹהִים.</p>\n<p>וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל - לִפְנִים מֵהַכֹּל, כְּנֶגְדּוֹ מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, זוֹ רוּחַ הָאֵם הָעֶלְיוֹנָה שֶׁמְּרַחֶפֶת עַל הַכֹּל. וְיַעֲקֹב הַשָּׁלֵם הוּא, וְזֶה מֹחַ הָאֱגוֹז, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וַדַּאי. אַחַר כָּךְ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כָּל אוֹתָן הַקְּלִפּוֹת, שֶׁכֻּלָּן יִהְיוּ מְשֻׁעְבָּדוֹת לוֹ.</p>\n<p>עַד כָּאן הָיָה כָּתוּב בְּאוֹתוֹ סֵפֶר שֶׁל הָרוֹפֵא הַקַּרְטִינָאִי. אַחַר כָּךְ הָיָה רָשׁוּם בַּכָּתוּב הַזֶּה: כָּל שְׁמִירָה שֶׁצָּרִיךְ רוֹפֵא חָכָם לַעֲשׂוֹת לְחוֹלֶה שֶׁשּׁוֹכֵב בְּבֵית חָלְיוֹ אֲסִירֵי הַמֶּלֶךְ, לַעֲבֹד לְרִבּוֹן הָעוֹלָם,</p>\n<p>שֶׁכְּשֶׁהוֹלֵךְ רוֹפֵא חָכָם אֵלָיו, יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ יְלֵל יְשִׁמֹן, מַחֲלוֹת שֶׁשּׁוֹרוֹת עָלָיו, מוֹצֵא אוֹתוֹ בַּאֲסִירֵי הַמֶּלֶךְ. אִם תֹּאמַר, הוֹאִיל וְהַקָּדוֹשׁ בָּרוּךְ הוּא יְצַוֶּה לִתְפֹּס אוֹתוֹ, שֶׁלֹּא יִשְׁתַּדֵּל שׁוּם אָדָם אַחֲרָיו - לֹא כָּךְ! שֶׁהֲרֵי דָּוִד אָמַר אַשְׁרֵי מַשְׂכִּיל אֶל דָּל וְגוֹמֵר. דַּל הוּא שֶׁשּׁוֹכֵב בְּבֵית חָלְיוֹ, וְאִם הָרוֹפֵא חָכָם, הַקָּדוֹשׁ בָּרוּךְ הוּא יִתֵּן בְּרָכוֹת לְאוֹתוֹ שֶׁמִּשְׁתַּדֵּל בּוֹ, וְאוֹתוֹ רוֹפֵא יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר, שׁוֹכֵב בְּבֵית חָלְיוֹ.</p>\n<p>וּבְתֹהוּ יְלֵל יְשִׁמֹן, שֶׁאוֹתָם חֳלָאִים דּוֹחֲקִים אוֹתוֹ. מַה צָּרִיךְ לוֹ לַעֲשׂוֹת? יְסֹבֲבֶנְהוּ, יְסוֹבֵב סִבּוֹת וְיָבִיא עִלּוֹת כְּדֵי שֶׁיִּמְנַע מִמֶּנּוּ אוֹתָם דְּבָרִים שֶׁמַּזִּיקִים לוֹ, יַקִּיז לוֹ וְיוֹצִיא מִמֶּנּוּ דָּם רַע. יְבוֹנֲנֵהוּ, יִסְתַּכֵּל וְיָבִין אוֹתוֹ הַחֹלִי מִמָּה הָיָה, וְיִסְתַּכֵּל כְּדֵי שֶׁלֹּא יִתְרַבֶּה עָלָיו וְיַנְמִיךְ אוֹתוֹ. אַחַר כָּךְ יִצְּרֶנְהוּ כְּאִישׁוֹן עֵינוֹ, כְּדֵי שֶׁיִּהְיֶה שָׁמוּר כָּרָאוּי בְּאוֹתָם מַשְׁקִים וּבְאוֹתָן רְפוּאוֹת שֶׁצָּרִיךְ לוֹ וְלֹא יִטְעֶה מֵהֶם, שֶׁאִלְמָלֵא יִטְעֶה אֲפִלּוּ בְּדָבָר אֶחָד, הַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲשִׁיב עַל הָרוֹפֵא כְּאִלּוּ שָׁפַךְ דָּם וַהֲרָגוֹ.</p>\n<p>כִּי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה שֶׁאַף עַל גַּב שֶׁאוֹתוֹ אָדָם הוּא בְּבֵית אֲסִירֵי הַמֶּלֶךְ, שֶׁיִּשְׁתַּדֵּל עָלָיו בֶּן אָדָם וִיסַיַּע לוֹ לְהוֹצִיאוֹ מִבֵּית הָאֲסוּרִים. וְהָיָה אוֹמֵר כָּךְ: הַקָּדוֹשׁ בָּרוּךְ הוּא דָּן דִּינֵי בְּנֵי הָעוֹלָם לְמַעְלָה הֵן לָמוּת, הֵן לְשָׁרֵשׁ, הֵן לַעֲקֹר, הֵן לָתֵת עֹנֶשׁ נְכָסִים. מִי שֶׁרָאוּי לְעֹנֶשׁ נְכָסִים נוֹפֵל בְּבֵית חָלְיוֹ, וְלֹא יִתְרַפֵּא עַד שֶׁעוֹשֶׂה כָּל מַה שֶּׁנִּגְזַר עָלָיו. כֵּיוָן שֶׁנֶּעֱנָשׁ בְּמָמוֹנוֹ וְנָתַן כָּל מַה שֶּׁנִּגְזַר עָלָיו, מִתְרַפֵּא וְיוֹצֵא מִבֵּית הָאֲסוּרִים, וְעַל זֶה צָרִיךְ לְהִשְׁתַּדֵּל עָלָיו שֶׁיִּתֵּן עֹנֶשׁ וְיֵצֵא.</p>\n<p>מִי שֶׁרָאוּי לְשָׁרֵשׁ, יִתְפְּסוּ אוֹתוֹ וְיִתְּנוּ אוֹתוֹ בְּבֵית הָאֲסוּרִים עַד שֶׁיִּשְׁתָּרֵשׁ מֵהַכֹּל, וְלִפְעָמִים שֶׁיִּשְׁתָּרֵשׁ מֵאֵיבָרִים אוֹ מֵאֶחָד מֵהֶם, וְאַחַר כָּךְ יוֹצִיאוּהוּ מִבֵּית הָאֲסוּרִים. מִי שֶׁרָאוּי לָמוּת כָּךְ זֶה, שֶׁאִלּוּ יִתֵּן כָּל כֹּפֶר וְכָל מָמוֹן שֶׁבָּעוֹלָם לֹא יִנָּצֵל,</p>\n<p>וְעַל זֶה צָרִיךְ רוֹפֵא חָכָם לְהִשְׁתַּדֵּל עָלָיו. אִם יָכוֹל לָתֵת לוֹ רְפוּאָה מִן הַגּוּף - יָפֶה, וְאִם לֹא - יִתֵּן לוֹ רְפוּאָה לְנִשְׁמָתוֹ וְיִשְׁתַּדֵּל עַל רְפוּאַת הַנְּשָׁמָה, וְזֶהוּ רוֹפֵא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׁתַּדֵּל עָלָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, עַד עַכְשָׁו לֹא שָׁמַעְתִּי מֵהָרוֹפֵא הַזֶּה וּמֵהַסֵּפֶר הַזֶּה, חוּץ מִפַּעַם אַחַת שֶׁאָמַר לִי סוֹחֵר אֶחָד שֶׁשָּׁמַע מֵאָבִיו, שֶׁרוֹפֵא אֶחָד הָיָה בְיָמָיו, שֶׁכְּשֶׁהָיָה מִסְתַּכֵּל בְּאָדָם כְּשֶׁהוּא בְּבֵית חָלְיוֹ, הָיָה אוֹמֵר: זֶה יִחְיֶה, וְזֶה יָמוּת. וְהָיוּ אוֹמְרִים עָלָיו (שהוא היה צדיק) יְרֵא חֵטְא, וְכָל מִי שֶׁלֹּא יָכוֹל הָיָה לְהַשִּׂיג (לקנות) מַה שֶּׁצָּרִיךְ, הוּא הָיָה קוֹנֶה לוֹ וְנוֹתֵן מִשֶּׁלּוֹ, וְהָיוּ אוֹמְרִים שֶׁאֵין חָכָם בָּעוֹלָם כְּמוֹתוֹ, וּבִתְפִלָּתוֹ הָיָה עוֹשֶׂה יוֹתֵר מִמַּה שֶּׁהָיָה עוֹשֶׂה בְיָדָיו, וּכְדוֹמֶה לָנוּ, זֶה הָיָה אוֹתוֹ רוֹפֵא.</p>\n<p>אָמַר אוֹתוֹ סוֹחֵר, וַדַּאי סִפְרוֹ בְיָדִי הוּא, שֶׁיְּרַשְׁתִּיו מִסָּבִי, וְכָל דִּבְרֵי אוֹתוֹ הַסֵּפֶר הִתְיַסְּדוּ כֻלָּם עַל סוֹדוֹת הַתּוֹרָה, וְסוֹדוֹת נִסְתָּרִים מָצָאתִי בוֹ. וְדִבְרֵי רְפוּאָה שֶׁהוּא אָמַר שֶׁלֹּא רָאוּי לַעֲשׂוֹתָם, פְּרָט לְמִי שֶׁהוּא יְרֵא חֵטְא,</p>\n<p>וְהֵם מִמַּה שֶּׁהָיָה עוֹשֶׂה בִלְעָם, שֶׁהָיָה לוֹחֵשׁ לְחָשִׁים עַל חוֹלֶה, וְהָיָה אוֹמֵר בְּפִיו וּמִיָּד מִתְרַפֵּא, וְכֻלָּם מְבֹרָרִים בְּאוֹתוֹ הַסֵּפֶר. וְאָמַר זֶה אָסוּר וְזֶה מֻתָּר לְמִי שֶׁיְּרֵא חֵטְא, מִשּׁוּם שֶׁחֲטָאִים רַבִּים אָמַר שֶׁרְפוּאָתָם תְּלוּיָה בְּלַחַשׁ הַפֶּה, וְהֵם מִצַּד הַנַּחַשׁ, וּמֵהֶם מִצַּד הַקֶּסֶם. וְכָל אוֹתָם שֶׁאָסוּר לוֹמַר בַּפֶּה וְאָסוּר לַעֲשׂוֹת בְּמַעֲשֶׂה הָיָה אוֹמֵר. עַד שֶׁמָּצָאתִי בְּמַחֲלוֹת יְדוּעוֹת שֶׁצָּרִיךְ לוֹמַר כָּךְ וּלְנַדּוֹת בְּנִדּוּי וּשְׁמָתָא עַל אוֹתוֹ חֹלִי, וְזוֹ תְמִיהָה גְדוֹלָה לָנוּ.</p>\n<p>שָׂמְחוּ רַבִּי אֶלְעָזָר וְשָׂמְחוּ הַחֲבֵרִים. אָמַר רַבִּי אֶלְעָזָר, אִם הָיָה לָנוּ סֵפֶר זֶה, נִרְאֶה מַהוּ. אָמַר, אֲנִי אֶמְסֹר בִּמְסִירָה עַל מְנָת לְהַרְאוֹת לַמְּנוֹרָה הַקְּדוֹשָׁה. וְשָׁנִינוּ, אָמַר רַבִּי אֶלְעָזָר, אוֹתוֹ סֵפֶר הָיָה בְיָדִי שְׁנֵים עָשָׂר חֳדָשִׁים, וּמָצָאתִי אוֹרוֹת עֶלְיוֹנִים. כְּשֶׁהִגַּעְתִּי לְאוֹתָם סוֹדוֹת שֶׁהָיוּ מִבִּלְעָם, תָּמַהְתִּי.</p>\n<p>יוֹם אֶחָד לָחַשְׁתִּי בְמָקוֹם אֶחָד, וְהָיוּ הָאוֹתִיּוֹת עוֹלוֹת וְיוֹרְדוֹת, עַד שֶׁרָאִיתִי בַחֲלוֹם וְאָמַר לִי, מַה לְּךְ לְהִכָּנֵס בִּתְחוּם שֶׁאֵינוֹ שֶׁלְּךְ? הִתְעוֹרַרְתִּי, וְהָיָה רַע לְפָנַי עַל סוֹדוֹת נִסְתָּרִים שֶׁהָיוּ שָׁם. שָׁלַחְתִּי לְאוֹתוֹ יְהוּדִי וְנָתַתִּי לוֹ הַסֵּפֶר,</p>\n<p>וּבַסּוֹדוֹת שֶׁל בִּלְעָם מָצָאתִי מֵאוֹתָם שְׁמוֹת הַמַּלְאָכִים שֶׁשָּׁלַח לוֹ בָּלָק וְלֹא הָיוּ מִסְתַּדְּרִים עַל תִּקּוּנֵיהֶם. אֲבָל כַּמָּה מִינֵי רְפוּאָה מָצָאתִי בוֹ שֶׁמְּתֻקָּנִים עַל תִּקּוּנֵי הַתּוֹרָה וְסוֹדוֹת נִסְתָּרִים שֶׁלָּהּ, וְרָאִיתִי בַחֲסִידוּת וּתְפִלּוֹת לַקָּדוֹשׁ-בָּרוּךְ- הוּא. וְאִם תֹּאמַר שֶׁהָיָה עוֹשֶׂה רְפוּאָה בִּפְסוּקֵי הַתּוֹרָה - חַס וְשָׁלוֹם! אֶלָּא הָיָה אוֹמֵר סוֹדוֹת הַתּוֹרָה, וְעַל אוֹתוֹ סוֹד מוֹצִיא סוֹדוֹת רְפוּאָה שֶׁלֹּא רָאִיתִי כָאֵלֶּה לְעוֹלָמִים. אָמַרְתִּי, בָּרוּךְ הָרַחֲמָן שֶׁהֶחְכִּים בְּנֵי אָדָם בְּחָכְמָה עֶלְיוֹנָה.</p>\n<p>וּמֵאוֹתָם דְּבָרִים שֶׁל בִּלְעָם לָקַחְתִּי, וְרָאִיתִי בָהֶם שֶׁלֹּא הָיָה בָעוֹלָם חָכָם בִּכְשָׁפִים כָּמוֹהוּ. אָמַרְתִּי, בָּרוּךְ הָרַחֲמָן שֶׁבִּטֵּל מֵהָעוֹלָם כְּשָׁפִים, כְּדֵי שֶׁלֹּא יִטְעוּ בְנֵי אָדָם מֵאַחַר יִרְאַת ה': ע\"כ מההשמטות.</p>"],[9522012745,"<p>וַיַּחֲלֹם וְהִנֵּה סֻלָּם (בראשית כח) - זוֹ הַתְּפִלָּה. מֻצָּב אַרְצָה, שֶׁמִּתְפַּלְלִים בְּנֵי אָדָם אוֹתָהּ בָּאָרֶץ, שֶׁהִיא הַשְּׁכִינָה, וּמַגִּיעָה לַשָּׁמַיִם, שֶׁהוּא הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנֶּאֱמַר (מלכים א ח) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. וְסוֹד הַדָּבָר - (תהלים ח) ה' אֲדנֵינוּ מָה אַדִּיר שִׁמְךְ בְּכָל הָאָרֶץ אֲשֶׁר תִּנָה הוֹדְךְ עַל הַשָּׁמָיִם.</p>\n<p>וּבִזְמַןֹ שֶׁמּוֹדִיעַ לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, הַשְּׁכִינָה שֶׁעוֹלָה בְּאוֹתָהּ תְּפִלָּה, מִיָּד - (בראשית כח) וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ, בְּאוֹתוֹ אָדָם. כֻּלָּם פּוֹתְחִים כַּנְפֵיהֶם לְעֻמַּת הַשְּׁכִינָה בְּאוֹתָהּ תְּפִלָּה. זֶהוּ שֶׁכָּתוּב (יחזקאל א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת מִלְמַעְלָה. וְזֶהוּ עֹלִים - שְׁכִינָה עַל כַּנְפֵיהֶם.</p>\n<p>וְיֹרְדִים בּוֹ, מַהוּ בּוֹ? בְּהַקָּדוֹשׁ בָּרוּךְ הוּא. וְהַקָּדוֹשׁ בָּרוּךָ הוּא יוֹרֵד עֲלֵיהֶם לְעֻמַּת הַשְּׁכִינָה, וּמִתְיַחֵד הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹ בְּאוֹתָהּ תְּפִלָּה. שֶׁהַשְּׁכִינָה הִיא מִצְוָה כְּלוּלָה מִשֵּׁם הֲוָיָ\"ה, יְהֹוָ\"ה הִיא חַיָּה שֶׁלּוֹ, וּמִצְוָה בְּלֹא מַחֲשָׁבָה אֵין לָהּ עֲלִיָּה. וּמַחֲשָׁבָה הִיא אָדָם - שֵׁם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, תִּפְאֶרֶת,</p>\n<p>מִצְוָה, הִיא מַלְכוּת כְּלוּלָה מֵאַרְבַּע חַיּוֹת שֶׁל הַמֶּרְכָּבָה כְּלוּלָה מֵאַרְבַּע אוֹתִיּוֹת, הִיא נְקֵבָה שֶׁלּוֹ, פָּנִים שֶׁלּוֹ, פָּנִים שֶׁל רַחֲמִים. בִּגְלָלָהּ נֶאֱמַר, (שמות לג) אִם אֵין פָּנֶיךְ הֹלְכִים אַל תַּעֲלֵנוּ מִזֶּה.</p>\n<p>וּמִצַד הַצַּדִּיק נִקְרָא אֲחוֹרָיו, חַיָּה כְּלוּלָה שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת, שֶׁהֵן מֵאֲחוֹרָיו שֶׁל הָאָדָם לְעֻמַּת שְׁמוֹנָה עָשָׂר נִעְנוּעִים שֶׁל הַלּוּלָב שֶׁדּוֹמֶה לַשִּׁדְרָה, שֶׁבּוֹ שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת, שֶׁהוּא אָחוֹר לְמַעֲשֵׂה בְרֵאשִׁית, וָקֶדֶם לְמַחֲשָׁבָה, שֶׁנֶּאֱמַר בָּהּ, יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה. מַה שֶּׁאֵין כֵּן בָּאָדָם, שֶׁעֵץ הַדַּעַת טוֹב וָרָע שֶׁהוּא אָחוֹר לְמַעֲשֶׂה, וָקֶדֶם לְפֻרְעָנוּת.</p>\n<p>קָמוּ תַנָּאִים וְאָמוֹרָאִים וְאָמְרוּ, רוֹעֶה נֶאֱמָן, יִתְקַיֵּם בְּךְ זֶה הַפָּסוּק, (ישעיה סב) אַל תִּתְּנוּ דֳמִי לוֹ. שֶׁהֲרֵי עֶלְיוֹנִים וְתַחְתּוֹנִים מְקַנְּנִים בַּצֶּלֶם שֶׁלְּךְ. מַחֲנוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֵם מִישִׁיבָה שֶׁל מַעְלָה, וּמַחֲנוֹת שֶׁל הַמַּלְכָּה שֶׁהֵם מִישִׁיבָה שֶׁל מַטָּה, עָלֶיךְ נֶאֱמַר (בראשית כח) וְהִנֵּה מַלְאֲכֵי אֱלֹהִים וְגוֹ'. בְּךְ עוֹלִים מַחֲנוֹת שֶׁל הַשְּׁכִינָה בַּתְּפִלָּה שֶׁלְּךְ, וְיוֹרְדִים מַחֲנוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַקָּדוֹשׁ בָּרוּךְ הוּא אֵצֶל הַשְּׁכִינָה בְּכַמָּה שִׁירִים וְנִגּוּנִים בַּתְּפִלָּה. וְאַתָּה הוּא הַקֵּרוּב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתְּפִלָּה שֶׁלְּךְ,</p>\n<p>שֶׁהִיא קָרְבָּן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ. בְּפָרָשַׁת (במדבר כח) צַו אֶת בְּנֵי יִשְׂרָאֵל, אֶת קָרְבָּנִי לַחְמִי, שֶׁתִּקְּנוּ בַּעֲלֵי הַמִּשְׁנָה קָרְבָּנוֹת בַּתְּפִלָּה מִצַּד הַיָּמִין, שֶׁשָּׁם אִישׁ חֶסֶד - כֹּהֵן. וְתִקְּנוּ אֲמִירַת הַזְּמִירוֹת שֶׁהֵם שִׁיר הַלְוִיִּם אַחֲרֵיהֶם - מִצַּד הַגְּבוּרָה. וְהוֹד, דַּרְגָּה שֶׁל דָּוִד הַמֶּלֶךְ, נִקְשָׁר בִּשְׂמֹאל. וְאַהֲרֹן, שֶׁדַּרְגָּתוֹ נֵצַ\"ח, נִקְשָׁר בְּחֶסֶד. זֶהוּ שֶׁכָּתוּב (תהלים טז) נְעִמוֹת בִּימִינְךְ נֶצַח.</p>\n<p>אַחַר כָּךְ יִחוּד בְּפָסוּק שְׁמַע יִשְׂרָאֵל, וְכוֹלֵל בְּרָכָה וּקְדֻשָּׁה, שֶׁהוּא קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, וּבְרָכָה מִצַּד הַיָּמִין. זֶהוּ שֶׁכָּתוּב (במדבר ו) דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרֲכוּ אֶת בְּנֵי יִשְׂרָאֵל. וּקְדֻשָּׁה מִצַּד הַלְוִיִּם, הָעַמּוּד הָאֶמְצָעִי, קִשּׁוּר יָמִין וּשְׂמֹאל, וְהוּא קֶשֶׁר שֶׁל תְּפִלִּין שֶׁל רֹאשׁ שֶׁהִיא אִמָּא עֶלְיוֹנָה, תְּפִלִּין עַל רֹאשׁוֹ, כְּמוֹ שֶׁפֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה בִּתְפִלִּין שֶׁל אֲדוֹן הָעוֹלָם מַה כָּתוּב בָּהֶן.</p>\n<p>וְהוּא קֶשֶׁר שֶׁל תְּפִלִּין שֶׁל יָד, שֶׁהִיא שְׁכִינָה תַּחְתּוֹנָה, וְזֶהוּ שֶׁפֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, הֶרְאָהוּ לְמֹשֶׁה קֶשֶׁר שֶׁל תְּפִלִּין.</p>\n<p>ש שֶׁל תְּפִלִּין מֹשֶׁה, כָּלוּל מִשְּׁלֹשָׁה עֲנָפִים שֶׁל הָאָבוֹת לְמַעְלָה, שֶׁתִּקְּנוּ שָׁלֹשׁ תְּפִלּוֹת שֶׁהֵן סִימַן שמ\"ע, שֶׁהִיא שַׁחֲרִי\"ת מִנְחָ\"ה עַרְבִי\"ת, מ\"ה שֶׁלְּךְ - תְּפִלַּת הַשַּׁבָּת, שֶׁנֶּאֱמַר בָּהּ (בראשית א) וּרְדוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וְגוֹ'.</p>\n<p>וְאַתָּה כּוֹלֵל מֶרְכָּבָה תַּחְתּוֹנָה שֶׁל אַהֲרֹן דָּוִד וּשְׁלֹמֹה וְאָדָם הָרִאשׁוֹן לְמַעְלָה, וּבַת זוּגוֹ לְמַטָּה, אֵם כָּל חַ\"י, שֶׁהוּא צַדִּיק חַי הָעוֹלָמִים. וּמִשּׁוּם זֶה אַהֲרֹן, אַף עַל גַּב שֶׁהוּא יָמִין, פֵּרְשׁוּהוּ חֲכָמִים בּוֹ, אַהֲרֹן שׁוֹשְׁבִין שֶׁל הַמַּלְכָּה. יַעָקֹב הוּא כָּלוּל מִשְּׁלֹשָׁה אָבוֹת, שֶׁבּוֹ רוֹכֵב אָדָם הָרִאשׁוֹן, שֶׁלֹּא לְחִנָּם פֵּרְשׁוּהוּ בַּעֲלֵי הַמִּשְׁנָה, יָפְיוֹ שֶׁל יַעֲקֹב כְּיָפְיוֹ שֶׁל אָדָם הָרִאשׁוֹן.</p>\n<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, רוֹעֶה נֶאֱמָן, רוֹאֶה אֲנִי שֶׁכָּפַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת שִׁמְךְ וְאָמַר מֹשֶׁה מֹשֶׁה, לִכְלֹל אוֹתְךְ בַּמֶּרְכָּבָה הָעֶלְיוֹנָה וּבַמֶּרְכָּבָה הַתַּחְתּוֹנָה, לִכְלֹל בְּךְ אֶת אָדָם הָרִאשׁוֹן מִצַּד הָאָבוֹת, וְלִכְלֹל בְּךְ אֶת חַוָּה מִצַּד אַהֲרֹן דָּוִד וּשְׁלֹמֹה.</p>\n<p>לָמָּה לֹא כָפַל שֵׁם יַעֲקֹב כָּךְ? אָמַר לוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה, מִשּׁוּם שֶׁקָּרָא לוֹ יַעֲקֹב וְיִשְׂרָאֵל. יַעֲקֹב לְשׁוֹן עָקֵב, כְּלוֹמַר נְקֵבָה, שֶׁנֶּאֱמַר עֲקֵבוֹ שֶׁל אָדָם הָרִאשׁוֹן הָיָה מַכְהֶה גַּלְגַּל חַמָּה. וְנִקְרָא יִשְׂרָאֵל, שֶׁשָּׁם רֹאשׁ הַזָּכָר, רֹאשׁ לַנְּקֵבָה, כְּלוֹמַר הֶעָקֵב. וְזֶהוּ שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַנָּחָשׁ, (בראשית ג) הוּא יְשׁוּפְךְ רֹאשׁ וְאַתָּה תְשׁוּפֶנּוּ עָקֵב. וְזֶה גָּרַם שְׁכִינָה בַּגָּלוּת, שֶׁנֶּאֱמַר בָּהּ (משלי כב) עֵקֶב עֲנָוָה יִרְאַת ה'.</p>\n<p>שָׂמַח רַבִּי שִׁמְעוֹן, וְשָׂמְחוּ בַּעֲלֵי הַמִּשְׁנָה וְאָמְרוּ, פֶּה שֶׁל הַשְּׁכִינָה, סִינַי, מִי יָכוֹל לַעֲמֹד (לפני) פִּיךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ מְדַבְּרִים בּוֹ, וְשִׁשִּׁים רִבּוֹא שֶׁל יְשִׁיבָה שֶׁל מַעְלָה וְשִׁשִּׁים רִבּוֹא שֶׁל יְשִׁיבָה שֶׁל מַטָּה מְדַבְּרִים בּוֹ עַל פִּיךְ. וְעָלֶיךְ נֶאֱמַר וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ.</p>\n<p>דָּבָר אַחֵר וְהִנֵּה סֻלָּם - פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, סִינַי זֶה סֻלָּם, וְהוּא קַל, וְסוֹד הַדָּבָר - (ישעיה יט) הִנֵּה ה' רֹכֵב עַל עָ\"ב קַ\"ל. ע\"ב - יו\"ד ה\"י וי\"ו ה\"י. וְעוֹד ע\"ב - י', י\"ה, יה\"ו, יְהֹוָ\"ה. קַ\"ל - יו\"ד, יו\"ד ה\"א, יו\"ד ה\"א וא\"ו, יו\"ד ה\"א וא\"ו ה\"א. אוֹתִיּוֹת רִאשׁוֹנוֹת עוֹלוֹת לְשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת, וְאוֹתָן תּוֹלָדוֹת שֶׁלָּהֶן עוֹלוֹת קַ\"ל. עָ\"ב קַ\"ל עוֹלִים מָאתַיִם וּשְׁנַיִם, כְּחֶשְׁבּוֹן ב\"ר. וְאַתָּה הוּא רוֹעֶה נֶאֱמָן, עָלֶיךְ נֶאֱמַר (תהלים ב) נַשְּׁקוּ בַר. וְאַתָּה רַב לְמַטָּה, רַבָּן שֶׁל כָּל יִשְׂרָאֵל, רַבָּן שֶׁל מַלְאֲכֵי הַשָּׁרֵת, בֵּן לְמַעְלָה, בֵּן לְהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ.</p>\n<p>נֶאֱמַר אֵצֶל דָּוִד, (שמואל ב יב) גַּם ה' הֶעֱבִיר חַטָּאתְךְ לֹא תָמוּת. בְּזֶה הַגַּם הִתְכַּפֵּר דָּוִד. וְזֶהוּ שִׁעוּר שֶׁל חַלָּה, שָׁלֹשׁ וְאַרְבָּעִים בֵּיצִים וְתוֹסֶפֶת חֹמֶשׁ בֵּיצָה, רָמוּז בַּנֶּאֱמַר (ויקרא ה) וַחֲמִישִׁתוֹ יוֹסֵף עָלָיו.</p>\n<p>אַשְׁרֵי הַתְּפִלָּה שֶׁיָּצְאָה מִפִּיךְ, כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָרַד עַל הַר סִינַי וְנֶאֱמַר בּוֹ (דברים כט) כִּי אֲשֶׁר יֶשְׁנוֹ פֹּה וְגוֹ'. כָּךְ בֵּן (כאשר) אַתָּה תִּשְׁתַּדֵּל בְּתוֹרָה וּתְפִלָּה, הַקָּדוֹשׁ בָּרוּךְ הוּא יֶאֱסֹף עֶלְיוֹנִים וְתַחְתּוֹנִים וְכָל אוֹתָן נְשָׁמוֹת שֶׁהָיוּ וְכָל הָעֲתִידִים לִהְיוֹת וְכָל מַחֲנוֹת הַמַּלְאָכִים וְיָרַד בַּצֶּלֶם שֶׁלְּךְ לְקַבֵּל הַתְּפִלָּה שֶׁלְּךְ וְהַתּוֹרָה שֶׁלְּךְ. מִשּׁוּם שֶׁמַּחֲשָׁבָה שֶׁלְּךְ לְיַחֵד לְהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּכָל מַחֲנוֹת שֶׁלּוֹ לְמַעְלָה וּמַטָּה</p>\n<p>בְּתוֹרָתְךְ וּבִתְפִלָּתְךְ. הַקָּדוֹשׁ בָּרוּךָ הוּא, מַחֲשָׁבָה טוֹבָה מְצָרְפָהּ לְמַעֲשֶׂה. וּכְמוֹ שֶׁהוּא אָמַר אָנֹכִי, וְכֻלָּם אָמְרוּ (שמות כד) נַעֲשֶׂה וְנִשְׁמָע - כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה לְכָל הַמַּחֲנוֹת שֶׁלּוֹ שֶׁכֻּלָּם שָׁתְקוּ וְשָׁמְעוּ לְדִבּוּרְךְ, מִשּׁוּם שֶׁרְצוֹנְךְ בָּהֶם לְיַחֵד לְהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּכָל הַמַּחֲנוֹת שֶׁלּוֹ.</p>\n<p>וְכָל מַה שֶּׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִבְטִיחַ לַעֲשׂוֹת לְךְ כַּמָּה טוֹבוֹת שֶׁאֵין לָהֶן סוֹף, כֻּלָּם אָמְרוּ נַעֲשֶׂה וְנִשְׁמָע. וּמִשּׁוּם זֶה נֶאֱמַר, (תהלים קג) בָּרְכוּ ה' מַלְאָכָיו גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ לִשְׁמֹעַ בְּקוֹל דְּבָרוֹ, וְהִתְחַזֵּק בְּךְ. שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא ושְׁכִינָתוֹ וְכָל הַמַּחֲנוֹת שֶׁלּוֹ הִסְכִּימוּ לַעֲשׂוֹת כָּל רְצוֹנְךְ וְיוֹתֵר, מַה שֶּׁהוּא כָּתוּב עַל יָדְךְ, וְלֹא נָפַל דָּבָר קָטָן מִכְּתִיבַת יָדְךְ שֶׁלֹּא הִתְקַיֵּם. אַשְׁרֵי הָאָדָם שֶׁאֲדוֹנוֹ חוֹשֵׁב אוֹתוֹ כְּגוּפוֹ וְעוֹשֶׂה לוֹ כָּבוֹד כְּצוּרָתוֹ לִהְיוֹת לוֹקֵחַ דְּבָרִים שֶׁל פִּיו בְּתוֹרָה וּתְפִלָּה כִּדְבָרָיו בְּהַר סִינַי. וְאֵין אֶחָד שֶׁפָּתַח פִּיו לְקַטְרֵג לוֹ אֶלָּא כֻּלָּם, עֶלְיוֹנִים וְתַחְתּוֹנִים, בְּהַסְכָּמָה אַחַת וּבְרָצוֹן אֶחָד.</p>"],[9522012746,"<p>אַחַר כָּךְ יֵשׁ לוֹ לִקְרֹא פָּרָשַׁת בְּרֵאשִׁית, עַד וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. שֶׁהִיא מְעֻלָּה וְשֶׁבַח שֶׁל הַכֹּל. אַחַר כָּךְ יִתְעַסֵּק בְּפָרָשַׁת הַקָּרְבָּנוֹת לְכַפֵּר עָלָיו. וְיֹאמַר, צַו אֶת אַהֲרֹן, עַד תּוּקַד בּוֹ, כְּדֵי שֶׁכָּל הִרְהוּרִים וּמַחֲשָׁבוֹת שֶׁל הַלַּיְלָה יִתְכַּפְּרוּ. אַחַר כָּךְ יְשַׁבַּח בַּתִּשְׁבָּחוֹת שֶׁל דָּוִד, וּמִשּׁוּם זֶה יִכָּנֵס אָדָם בַּשְּׁעָרִים שֶׁבָּהֶם הַכֹּל, וְהוּא מְתַקֵּן הַמַּדְרֵגוֹת.</p>\n<p>כֵּיוָן שֶׁהִגִּיעַ לְיוֹצֵר אוֹר, שֶׁהוּא תְּחִלַּת הַתְּפִלָּה דְּמִיֹּשֶׁב, אָז כָּל אוֹתָן הַמַּדְרֵגוֹת פּוֹתְחוֹת שְׁעָרִים, וְאָז (שיר השירים ג) כְּתִימְרוֹת עָשָׁן כָּתוּב. מַה תִּימְרוֹת עָשָׁן שֶׁל קְטֹרֶת עוֹלָה וּמִתְחַבְּרִים מַדְרֵגוֹת אֵלּוּ בְאֵלּוּ, אַף כָּאן הִיא תְפִלָּה, שֶׁהִיא כְתִימְרוֹת עָשָׁן שֶׁמִּתְחַבְּרִים וּמִתְקַשְּׁרִים אֵלּוּ בְאֵלּוּ. שֶׁהֲרֵי הוּא קוֹשֵׁר לָהֶם וְאוֹמֵר, כֻּלָּם אֲהוּבִים כֻּלָּם קְדוֹשִׁים וְכוּ'.</p>\n<p>אַחַר כָּךְ אַהֲבָה רַבָּה, לַעֲלוֹת וּלְהִתְקַשֵּׁר בְּיָמִין וְיִחוּד שֶׁל שְׁמַע. ע' גְּדוֹלָה, ד' גְּדוֹלָה, וְהַסִּימָן - עֵ\"ד. זֶה שֶׁכָּתוּב (שמואל א יב) עֵ\"ד ה' בָּכֶם. נִשְׁאֲרוּ אוֹתִיּוֹת ש\"מ בְּמ' פְּתוּחָה. לְפִי שֶׁמ' פְּתוּחָה מֶלֶךְ תַּחְתּוֹן, מֵ\"ם סְתוּמָה מֶלֶךְ עֶלְיוֹן. נִשְׁאֲרוּ אוֹתִיּוֹת ש\"מ א\"ח, מֵהַצַּד הַזֶּה ש\"מ, וּמֵהַצַּד הַזֶּה א\"ח.</p>\n<p>אָמַר רַב הַמְנוּנָא סָבָא, כָּל מִי שֶׁמְּיַחֵד זֶה בְּכָל יוֹם, שִׂמְחָה מְזֻמֶּנֶת לוֹ מִלְמַעְלָה מֵאוֹתִיּוֹת אֵלּוּ. ש\"מ מִצַּד זֶה, א\"ח מִצַּד זֶה. וּמְצָרֵף אוֹתִיּוֹת אֵלּוּ - בַּסּוֹף מַתְחִיל וּבְיֹשֶׁר סִיֵּם. וְסִימָנָךְ - אֶשְׂמַח, שֶׁכָּתוּב (תהלים קד) אָנֹכִי אֶשְׂמַח בַּה'. בַּה' מַמָּשׁ. וְכָךְ נִמְצָא בְסִפְרוֹ שֶׁל חֲנוֹךְ.</p>\n<p>עוֹד, יֵשׁ בּוֹ אוֹת ע' גְּדוֹלָה, רֶמֶז לְאֵלּוּ שִׁבְעִים שֵׁמוֹת, סוֹד שֶׁל הָאָבוֹת הַקְּדוֹשִׁים. יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' - אֵלּוּ אַרְבָּעָה בָתִּים שֶׁל הַתְּפִלִּין שֶׁמְּאַחֵד לָהֶם (א\"ח). ד' גְּדוֹלָה זֶה קֶשֶׁר שֶׁל תְּפִלִּין שֶׁהִיא אֲחוּזָה בָהֶם, וְהוּא סוֹד לַחֲכָמִים, וְלֹא נִמְסָר לְגַלּוֹת.</p>\n<p>וּשְׁתֵּי רְצוּעוֹת יוֹצְאוֹת מִצַּד זֶה וּמִצַּד זֶה - סוֹד שֶׁל שְׁתֵּי יְרֵכַיִם שֶׁל זֶה א\"ח שֶׁנְּבִיאֵי אֱמֶת אֲחוּזִים בּוֹ. וְעוֹד א\"ח, רֶמֶז לַפָּסוּק שֶׁאָמַר (שיר השירים ה) פִּתְחִי לִי אֲחֹתִי, וְאַחַר כָּךְ אֱמֶת וְיַצִּיב. וּמַדּוּעַ וְיַצִּיב זֶה תַרְגּוּמוֹ? אֶלָּא זֶה יַעֲקֹב וְזֶה יוֹסֵף, וְצָרִיךְ לְהִתְדַּבֵּק בִּשְׁנֵיהֶם.</p>\n<p>וְאַחַר כָּךְ תְּפִלָּה שֶׁל עֲמִידָה. שְׁלֹשָׁה רִאשׁוֹנוֹת שֶׁהֵן מָגֵן, וּמְחַיֵּה, וְהָאֵל הַקָּדוֹשׁ. מָגֵן יֵשׁ בָּהּ אַרְבָּעִים וּשְׁתַּיִם תֵּבוֹת, סוֹד שֶׁל שֵׁם הַקָּדוֹשׁ שֶׁל אַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת. וְיֵשׁ לִכְלֹל לוֹ בַּלֵּב וּלְהִתְקַשֵּׁר כְּשַׁלְהֶבֶת בְּגַחֶלֶת בְּאַהֲבָה. וְזוֹ הִיא בְּרָכָה שֶׁל הַיָּמִין.</p>\n<p>מְחַיֵּה - יֵשׁ בָּהּ מ\"ט תֵּבוֹת, בְּסוֹד שֶׁל חֲמִשִּׁים שְׁעָרִים חָסֵר אֶחָד. וְיֵשׁ שֵׁם בִּגְבוּרָה ה', וְהוּא אַ'תָּ\"ה גִ'בּוֹר לְ'עוֹלָם אֲ'דֹנָ\"י, וְסוֹד שֶׁלּוֹ אגל\"א, וּבְסוֹד אַחֵר יגל\"א. וְהַכֹּל סוֹד אֶחָד מִגְּבוּרוֹת שֶׁל הַבְּרָכוֹת שֶׁל יְהוּדָה (בראשית מט): אַ'תָּה יוֹדוּךְ אַחֶיךְ, גּ'וּר אַרְיֵה יְהוּדָה, לֹ'א יָסוּר שֵׁבֶט מִיהוּדָה, אֹ'סְרִי לַגֶּפֶן עִירֹה. בָּזֶה מִתְעוֹרֵר יְהוּדָה בִּגְבוּרָה קְדוֹשָׁה, וְזוֹ הִיא בִּרְכַּת הַשְּׂמֹאל.</p>\n<p>בַּקְּדֻשָּׁה יֵשׁ אַרְבַּע עֶשְׂרֵה תֵבוֹת, עֶשֶׂר אֲמִירוֹת וְאַרְבַּע אוֹתִיּוֹת. וְזֶה כּוֹלֵל לְכָל הַצְּדָדִים וּמְאַחֵד מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם. שָׁלֹשׁ אַחֲרוֹנוֹת אֵינָן בְּחֶשְׁבּוֹן זֶה שֶׁל הַתֵּבוֹת, וְהֵן רְצֵה וּמוֹדִים, שְׁנֵי עַמּוּדִים תּוֹמְכֵי הַתּוֹרָה. שִׂים שָׁלוֹם - עֵץ הַחַיִּים שֶׁהוּא שְׁלוֹם הַבַּיִת, שָׁלוֹם שֶׁל הַכֹּל. וּבֵינֵיהֶם בְּאֶמְצָעִיתָם אֵלּוּ הַבְּרָכוֹת שֶׁתִּקְּנוּ הַקַּדְמוֹנִים, וְכָךְ בֵּאֲרוּהָ.</p>\n<p>לְאַהַד שֶׁסִּיֵּם תְּפִלָּתוֹ וְהוֹדָה עַל חֲטָאָיו - נְפִילַת אַפַּיִם. שֶׁכָּךְ בֵּאֲרוּהָ, שֶׁיַּעֲשֶׂה כָּל מַה שֶּׁעָשָׂה מֹשֶׁה רַבֵּנוּ, עָלָיו הַשָּׁלוֹם, תְּפִלּוֹת וְתַחֲנוּנִים וּבַקָּשׁוֹת וּנְפִילַת אַפַּיִם, שֶׁכָּתוּב (דברים ט) וָאֶתְנַפַּל לִפְנֵי ה'. וְכֵיוָן שֶׁנִּכְנַס בְּכָל אֵלּוּ הַמַּדְרֵגוֹת הָעֶלְיוֹנוֹת וְנִקְשַׁר הַכֹּל בְּכֻלָּם, יֵשׁ לָרֶדֶת לְמַטָּה. הוֹאִיל וְיָרַד לְמַטָּה, צָרִיךְ נְפִילַת אַפַּיִם בְּאָלֶף בֵּית.</p>\n<p>מָה הַטַּעַם? כֵּיוָן שֶׁהִתְפַּלֵּל תְּפִלָּתוֹ וְהוֹדָה עַל חֲטָאָיו, מִכָּאן וּלְהָלְאָה מַרְאֶה עַצְמוֹ שֶׁמּוֹסֵר נַפְשׁוֹ לְקוֹנוֹ בְּאַהֲבָה, שֶׁכָּתוּב (תהלים כה) אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא. וְנוֹחַ לוֹ לְאוֹתוֹ צַד שֶׁמְּצוּיָה בוֹ מִיתָה, עוֹשֶׂה לוֹ נַחַת.</p>\n<p>וְעַל זֶה בְּאַלְפָא בֵּיתָא זוֹ אֵין בָּהּ לֹא וָא\"ו וְלֹא קוֹ\"ף וְלֹא בֵּי\"ת, וְיֵשׁ בָּהּ אוֹת פ' בִּמְקוֹמָהּ (בסופה). מִי שֶׁמָּסַר טַעֲמוֹ מִשּׁוּם שֶׁנְּפִילָה זוֹ שֶׁמּוֹסֵר בֶּן אָדָם נַפְשׁוֹ לְמִיתָה, צָרִיךְ לְכַוֵּן רְצוֹנוֹ וְלַעֲשׂוֹת נַחַת רוּחַ לַצַּד הַהוּא שֶׁמְּצוּיָה בוֹ מִיתָה, כְּמוֹ שֶׁעוֹשֶׂה הַקּוֹף בֶּחָרָבָה בֶהָרִים; מַרְאֶה עַצְמוֹ כְּמוֹ מֵת בִּפְנֵי הַחַיּוֹת, מִשּׁוּם שֶׁמְּפַחֵד מֵהֶם, וְכַאֲשֶׁר מִתְקָרְבִים אֵלָיו וְחוֹשְׁבִים לֶאֱכֹל וְלַהֲרֹג אוֹתוֹ, רוֹאִים אוֹתוֹ שֶׁנּוֹפֵל וּמֵת, וְחוֹשְׁבִים שֶׁהוּא מֵת, וְאָז חוֹזְרִים לַאֲחוֹרֵיהֶם. וְעַל זֶה הִסְתַּלְּקוּ שָׁלֹשׁ אוֹתִיּוֹת אֵלּוּ שֶׁלֹּא יָדְעוּ בָהֶם אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעַצְמוֹ.</p>\n<p>וְעִם כָּל זֶה, בִּרְצוֹן הַלֵּב מֵשִׂים עַצְמוֹ וּמוֹסֵר לוֹ נַפְשׁוֹ בְּאַהֲבָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חוֹשֵׁב עָלָיו כְּאִלּוּ נוֹטֵל נִשְׁמָתוֹ מִמֶּנּוּ. מִשּׁוּם שֶׁיֵּשׁ חֲטָאִים שֶׁעוֹשֶׂה אָדָם שֶׁלֹּא מִתְכַּפְּרִים אֶלָּא בְשָׁעָה שֶׁיּוֹצֵאת נִשְׁמָתוֹ מִמֶּנּוּ מִזֶּה הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ישעיה כב) אִם יְכֻפַּר הֶעָוֹן הַזֶּה לָכֶם עַד תְּמֻתוּן. וְעַתָּה שֶׁנֶּחְשַׁךְ בַּעֲדוֹ, שֶׁנָּטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת נִשְׁמָתוֹ וְהוּא נָתַן לוֹ בִרְצוֹנוֹ, וְאוֹתָהּ שָׁעָה עוֹמֶדֶת לְכַפָּרָה עַל כָּל חֲטָאָיו וְהִשְׁלִים לְכָל הַצְּדָדִים וּלְאוֹתוֹ צַד שֶׁנִּתְבָּאֵר.</p>\n<p>וְעִם כָּל זֶה עוֹלָה וְנִכְנֶסֶת בֵּין שְׁתֵּי זְרוֹעוֹת בְּחִבּוּק שֶׁל אַהֲבָה כְּמוֹ שֶׁצָּרִיךְ, וְהִיא מְקֻטֶּרֶת מֹר וּלְבוֹנָה מִכֹּל אַבְקַת רוֹכֵל.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אָסוּר לוֹ לָאָדָם לִטְעֹם כְּלוּם עַד שֶׁיֹּאכַל הַמֶּלֶךְ הָעֶלְיוֹן, וּמַה הוּא? תְּפִלָּה. וּתְפִלָּה שֶׁל אָדָם כְּגוֹן זֶה. בָּרִאשׁוֹנָה מַזְמִין לַצּוּרוֹת שֶׁחֲקוּקוֹת בַּכִּסֵּא עַל אֵלּוּ הַבְּרִיּוֹת שֶׁמִּתְפַּשְּׁטוֹת הָרוּחוֹת שֶׁלָּהֶם (יסוד) בְּיִחוּד בְּזֶה הָעוֹלָם מֵהֶם, וְזֶה שֶׁכָּתוּב (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה וְגוֹ'. שֶׁאֵיבָרִים שֶׁרְאוּיִים לְקָרְבָּן, רוּחַ שֶׁלָּהֶם מִתְפַּשֶּׁטֶת עֲלֵיהֶם אַרְבַּע צוּרוֹת וּמְזֻמֶּנֶת עַל בְּרִיּוֹת אֵלּוּ. וְזֶה שֶׁאָנוּ אוֹמְרִים וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ, וְכָל אוֹתָם חֲיָלוֹת אֲחֵרִים שֶׁהֵם מִתְפַּשְּׁטִים מֵהֶם.</p>\n<p>וּלְבַסּוֹף כֹּהֵן גָּדוֹל אוֹמֵר שֵׁם אֶחָד קָדוֹשׁ, וְזֶה אַהֲבַת עוֹלָם אֲהַבְתָּנוּ וְגוֹ'. וְיִחוּד גָּדוֹל מְיַחֲדִים, וְזֶה (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. וְאַחַר כָּךְ הַלְוִיִּם הֵם מְעוֹרְרִים לְנִגּוּן, וְזֶהוּ (דברים יא) וְהָיָה אִם שָׁמֹעַ תִּשְׁמְעוּ וְגוֹ'. זֶה נִגּוּן הַלְוִיִּם כְּדֵי לְעוֹרֵר צַד אֶחָד. וְאַחַר יִשְׂרָאֵל, זֶה אֱמֶת וְיַצִּיב, יִשְׂרָאֵל סָבָא שֶׁעוֹמֵד עַל הַקָּרְבָּן. זוֹ הִיא מַדְרֵגוֹת עֶלְיוֹנוֹת פְּנִימִיּוֹת, וְהַכֹּל עוֹמֵד עַל הַשֻּׁלְחָן.</p>\n<p>אֲבָל אֵין רְשׁוּת לְאֶחָד מֵהֶם לְהוֹשִׁיט יָדוֹ וְלֶאֱכֹל מִן הַקָּרְבָּן עַד שֶׁהַמֶּלֶךְ הָעֶלְיוֹן יֹאכַל, וְהֵם שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת. כֵּיוָן שֶׁהוּא אוֹכֵל, נוֹתֵן רְשׁוּת לְאַרְבַּע צוּרוֹת וּלְכָל אֵלּוּ הַצְּדָדִים שֶׁמִּתְפַּשְּׁטִים מִמֶּנּוּ, לֶאֱכֹל.</p>\n<p>אָז אָדָם שֶׁהוּא צוּרָה שֶׁכּוֹלֵל כָּל הַשְּׁאָר, יוֹרֵד וְנוֹפֵל עַל פָּנָיו וּמוֹסֵר רוּחוֹ וְעַצְמוֹ לְגַבֵּי אָדָם שֶׁחָקוּק עַל אֵלּוּ הַצּוּרוֹת וּלְעוֹרֵר לוֹ עָלָיו כְּמוֹ שֶׁרָאוּי, וְזֶה אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא. שָׁלֹשׁ צוּרוֹת אֲחֵרוֹת, וְכָל אֵלּוּ שֶׁמִּתְפַּשְּׁטִים מֵהֶם - תְּהִלָּה לְדָוִד, וְזֶה יַבִּיעוּ יְרַנֵּנוּ יֹאמֵרוּ יְדַבֵּרוּ - כֻּלָּם אוֹכְלִים וְנֶהֱנִים כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ.</p>\n<p>מִכָּאן וְאֵילָךְ יֹאמַר אָדָם צָרַת לִבּוֹ, (תהלים כ) יַעַנְךְ ה' בְּיוֹם צָרָה. צָרָה עַל הַמְעֻבֶּרֶת שֶׁיּוֹשֶׁבֶת עַל הַמַּשְׁבֵּר, וּמִתְהַפְּכִים כֻּלָּם לִהְיוֹת סָנֵגוֹרִים עַל הָאָדָם. וְשָׁלֹשׁ פְּסִיעוֹת שֶׁעוֹשֶׂה, הַכַּוָּנָה בָּהֶן לְמִיכָאֵ\"ל וְגַבְרִיאֵ\"ל רְפָאֵ\"ל שֶׁיָּצָא מִשָּׁלֹשׁ מַחֲנוֹת שְׁכִינָה, וְעַל זֶה כָּתוּב (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו. (ע\"כ מההשמטות)</p>"],[9522012747,"<p>צֶלֶם עַל אָדָם כִּסֵּא מְרֻבָּע בְּאַרְבַּע חַיּוֹת וְאָדָם לָשֶׁבֶת עַל הַכִּסֵּא. כָּל אֵיבָר וְאֵיבָר שֶׁל זֶה הַצֶּלֶם הוּא מַלְאָךְ שֶׁהוּא מְמֻנֶּה עַל כָּל מִצְוָה וּמִצְוָה, כְּמוֹ שֶׁבֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, עָשָׂה מִצְוָה אַחַת - קָנָה לוֹ פְּרַקְלִיט אֶחָד.</p>\n<p>צֶלֶם בָּרְשָׁעִים עֲבוֹדָה זָרָה, אַרְבַּע חַיּוֹת שֶׁלּוֹ - עָוֹן מַשְׁחִית אַף וְחֵמָה, אַרְבַּע פָּנִים שֶׁל עֲבוֹדָה זָרָה - נִדָּה שִׁפְחָה גּוֹיָה זוֹנָה. וּמִשּׁוּם זֶה, (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ, זֶה מְטַטְרוֹ\"ן. מִי הָאֱלֹהִים שֶׁבָּרָא אוֹתוֹ? זֶה אֱלֹהִים חַיִּים וּמֶלֶךְ עוֹלָם. בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ, סָמָאֵ\"ל, שֶׁמִּמֶּנּוּ אֱלֹהִים אֲחֵרִים, שֶׁנֶּאֱמַר בּוֹ (שמות כ) לֹא יִהְיֶה לְךְ אֱלֹהִים אֲחֵרִים עַל פָּנָי.</p>\n<p>אִם זָכָה - בָּרָא אוֹתוֹ אֱלֹהִים בְּצֶלֶם שֶׁל מְטַטְרוֹ\"ן, עֶבֶד תַּחַת רַבּוֹ. וְזֶהוּ וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ, בְּזוֹ הַצּוּרָה. וְאִם לֹא זָכָה - צֶלֶם שֶׁל סָמָאֵ\"ל. לָמַדְנוּ, מַלְאַךְ הַמָּוֶת שֶׁהוּא תַחַת רְשׁוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לָדוּן בּוֹ אָדָם בַּגֵּיהִנָּם, אִם לֹא שֶׁהוּא צַדִּיק.</p>\n<p>וּמִשּׁוּם זֶה וַיִּיצֶר, יְצִירָה לְטוֹב, מְטַטְרוֹ\"ן, לַעֲשׂוֹת (להיות) לוֹ עוֹזֵר בַּתּוֹרָה בַּמִּצְווֹת, וְזֶהוּ אֶעֱשֶׂה לּוֹ עֵזֶר. וְאִם לֹא זָכָה, יְצִירָה לְרַע, סָמָאֵ\"ל, שֶׁהוּא כְנֶגְדּוֹ לְהַחֲטִיא אוֹתוֹ לָדוּן אוֹתוֹ בַּגֵּיהִנָּם. וּשְׁנֵיהֶם הוֹלְכִים עִם הָאָדָם בִּשְׁנֵי צְלָמִים.</p>\n<p>וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים - זֶה הַצֶּלֶם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שְׁכִינָה, שֶׁנֶּאֱמַר בָּהּ וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט בַּצֶּלֶם הַזֶּה עַל שְׁנֵיהֶם, וְהַצֶּלֶם הַזֶּה תֵּבַת נֹחַ. עוֹרֵב וּבַת זוּגוֹ, כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בַגָּלוּת רוֹמֵז סוֹד זֶה.</p>\n<p>וַיְשַׁלַּח אֶת הָעֹרֵב - בָּרִאשׁוֹנָה. זֶה יֵצֶר הָרָע שֶׁשָּׁלַח לוֹ עִם הָאָדָם בָּעוֹלָם הַזֶּה שֶׁמַּקְדִּים, כְּמוֹ שֶׁהִקְדִּים לְיַעֲקֹב וּכְמוֹ שֶׁתֶּבֶן מַקְדִּים לַחִטָּה. אִם נִמְצָא הַגּוּף הַהוּא מְחֻיָּב בְּכַמָּה חוֹבוֹת, מְלֻכְלָךְ בְּטִנֹּפֶת הָעֲבֵרוֹת, נֶאֱמַר בּוֹ וְלֹא חָזַר הָעוֹרֵב בַּשְּׁלִיחוּת שֶׁל אֲדוֹנוֹ. לְבַסּוֹף - וַיְשַׁלַּח אֶת הַיּוֹנָה מֵאִתּוֹ. זֶה יֵצֶר הַטּוֹב (ע\"כ מההשמטות):</p>"],[9522012748,"<p>מִצְוָה לְיַבֵּם אֵשֶׁת הָאָח. וְסוֹד זֶה הֲרֵי בֵּאַרְנוּ, שֶׁהוּא עוֹשֶׂה טוֹב וֶאֱמֶת עִם אָחִיו הַמֵּת שֶׁלֹּא יִכָּרֵת מֵהָעוֹלָם הַהוּא. מִשּׁוּם שֶׁאוֹתוֹ אָדָם שֶׁמֵּת בְּלֹא בָנִים, לֹא עָבַר כֹּתֶל שֶׁל בַּרְזֶל לְהִכָּנֵס תּוֹךְ הֵיכַל הַמֶּלֶךְ.</p>\n<p>מִשּׁוּם שֶׁכֹּתֶל שֶׁל בַּרְזֶל קַיָּם בֵּין הָעוֹלָם הַזֶּה לָעוֹלָם הָאַחֵר, וְאַחַר אוֹתוֹ הַכֹּתֶל עוֹמְדִים אֶלֶף וְשִׁשִּׁים רִבּוֹא מַלְאֲכֵי חַבָּלָה, וְכֻלָּם נִקְרָאִים בַּעֲלֵי מָגִנִּים, בַּעֲלֵי אֵיבָה. חֲרָבוֹת מְשֻׁנָּנוֹת שֶׁל אֵשׁ לוֹהֲטוֹת בִּידֵיהֶם. וְתוֹךָ אוֹתוֹ כֹתֶל יֵשׁ (בו) שִׁשִּׁים אֶלֶף הֵיכָלוֹת שֶׁל חֹשֶׁךְ. וְכָל הֵיכָל וְהֵיכָל יֵשׁ בּוֹ חַלּוֹנוֹת פְּתוּחִים לַגֵּיהִנָּם.</p>\n<p>וְכָל אֵלּוּ שֶׁלֹּא זָכוּ בְּבָנִים בָּעוֹלָם הַזֶּה, כַּאֲשֶׁר יוֹצְאִים מִמֶּנּוּ וְהוֹלְכִים לְהִכָּנֵס לְאוֹתוֹ עוֹלָם אַחֵר וּפָגְעוּ תוֹךְ אוֹתוֹ כֹתֶל, וְיוֹצְאִים כָּל אֵלּוּ בַּעֲלֵי מָגִנִּים וְטוֹרְדִים אוֹתָם, וּמַכְנִיסִים אוֹתָם תּוֹךְ אֵלּוּ הַהֵיכָלוֹת וְיוֹשְׁבִים שָׁם עַד שֶׁיִּגָּאֲלוּ. וּבְכָל יוֹם וָיוֹם טוֹעֲמִים טַעַם שֶׁל גֵּיהִנָּם, אַף עַל גַּב שֶׁהוּא זַכַּאי, חוּץ מֵאִם שֶׁזְּכוּתוֹ גְדוֹלָה וּזְכוּת אֲבוֹתָיו. וְאֵלּוּ הֵם שֶׁהִשְׁתַּדְּלוּ בָהֶם וְלֹא יָכְלוּ. מִשּׁוּם שֶׁכָּל אֵלּוּ שֶׁלֹּא הִתְפַּשְּׁטָה מֵהֶם הַצּוּרָה שֶׁל מַעְלָה בְּזֶה הָעוֹלָם, לֹא עוֹלִים תּוֹךְ הָעוֹלָם הַהוּא.</p>\n<p>וְכָל אֵלּוּ שֶׁלֹּא הִשְׁתַּדְּלוּ בְּזֶה הָעוֹלָם בְּבָנִים, כַּאֲשֶׁר יוֹצְאִים מִזֶּה הָעוֹלָם מִתְקָרְבִים תּוֹךְ הַכֹּתֶל הַזֶּה, וְיוֹצְאִים אוֹתָם בַּעֲלֵי מָגִנִּים וְטוֹרְדִים אוֹתָם בְּאֵשׁ לוֹהֶטֶת. וְתוֹךְ אֵלּוּ הַהֵיכָלוֹת יֵשׁ הֵיכָל אֶחָד, וְאוֹתוֹ הֵיכָל נִקְרָא הֵיכַל פּוֹעֲלֵי אָוֶן, וְלוֹקְחִים אוֹתוֹ וּמַכְנִיסִים אוֹתוֹ בְּאוֹתוֹ הֵיכָל, וְשָׁם נִטְרָד בְּכָל יוֹם וָיוֹם, וְזֶה קָשֶׁה מִגֵּיהִנָּם. אִם יֵשׁ לוֹ גוֹאֵל - טוֹב, וְאִם לֹא - לֹא יוֹצֵא מִשָּׁם לְעוֹלָמִים. וְעַל זֶה כָּתוּב (תהלים קכז) אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ מֵהֶם וְגוֹ'.</p>\n<p>כַּאֲשֶׁר יֵשׁ לָהֶם גּוֹאֵל לְאֵלּוּ שֶׁלֹּא זָכוּ, צָרִיךְ לְאוֹתָהּ אִשָּׁה מַמָּשׁ שֶׁהוּא עָזַב שָׁם, בְּמָקוֹם שֶׁנַּפְשׁוֹ וּרְצוֹנוֹ הָיָה שָׁם תָּמִיד וְנִדְבַּק בְּרָצוֹן וְהִשְׁתּוֹקְקוּת. וְכַאֲשֶׁר הִשְׁתַּמֵּשׁ בְּאוֹתוֹ מָקוֹם אָחִיו שֶׁל הַמֵּת, אוֹתָהּ הִתְדַבְּקוּת שֶׁל הַתְּשׁוּקָה שֶׁל הַנֶּפֶשׁ שֶׁעָזַב בְּאוֹתוֹ מָקוֹם מִתְעוֹרֶרֶת בְּהִתְעוֹרְרוּת הָאִשָּׁה שֶׁמִּתְעוֹרֶרֶת אֵלָיו וְאָחִיו שֶׁשָּׂם רְצוֹנוֹ בְאַחֲוָה בְּאוֹתוֹ מָקוֹם. אָז הִתְעוֹרְרוּת זוֹ מְעוֹרֶרֶת לְאוֹתוֹ מֵת בְּאֵלּוּ הַהֵיכָלוֹת וְיוֹצֵא מִשָּׁם.</p>\n<p>וּמְמֻנֶּה אֶחָד מֵאֵלּוּ בַּעֲלֵי מָגִנִּים בָּא עִמּוֹ, וְחוֹזֵר אָדָם לְאוֹתוֹ מָקוֹם וְיָשׁוּב לִימֵי עֲלוּמָיו. אוֹתוֹ מְמֻנֶּה קוֹרֵא עָלָיו: אוֹי שֶׁיָּצָא שְׂכָרוֹ בְּהֶפְסֵדוֹ. מִי שֶׁהָיָה זָקֵן, חוֹזֵק תִּינוֹק לְצַחֵק בּוֹ. וְעִם כָּל זֶה, הַקָּדוֹשׁ בָּרוּךְ הוּא רְצוֹנוֹ לַעֲשׂוֹת עִמּוֹ טוֹבָה לְתַקְּנוֹ בְּזֶה הָעוֹלָם, וְזֶהוּ שֶׁאֲדוֹנוֹ מִתְרַצֶּה בוֹ. נַעַר מִשְּׁתֵּים עֶשְׂרֵה שָׁנִים שֶׁלֹּא הִשְׁלִים לְעֶשְׂרִים אוֹ שֶׁהוּא נַעַר שֶׁלֹּא נָשׂוּי, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹקֵר אוֹתוֹ, וְשׁוֹתֵל אוֹתוֹ לְבַסּוֹף בְּצַד אָבִיו בְּקֹשִׁי, וְזֶה לֹא הוֹלֵךְ לְאוֹתוֹ כֹתֶל.</p>\n<p>בֵּין גַּן עֵדֶן וְגֵיהִנָּם יֵשׁ סֶלַע אֶחָד, וְזֶה הוּא סֶלַע הַמַּחֲלֹקֶת. מַדּוּעַ נִקְרָא כָּךְ? מִשּׁוּם שֶׁכָּל בְּנֵי הָעוֹלָם עוֹשִׂים מַחֲלֹקֶת בְּרִבּוֹנָם עַל אוֹתוֹ נַעַר. וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה בּוֹ שֶׁלֹּא יַצְלִיחַ, שֶׁאִם יִתְקַשֶּׁה, לֹא נִנְטַע בַּנְּטִיעָה טוֹב. וְעַתָּה שֶׁהוּא רַךְ וְרָאוּי לְעָקְרוֹ, נֶעֱקָר, וְשׁוֹתֵל אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>כַּאֲשֶׁר נֶעֱקָר, עוֹלֶה אֵצֶל אוֹתוֹ סֶלַע, וְשָׁם הֵיכָלוֹת יְדוּעִים לְאֵלּוּ, וַחֲיָלוֹת וּמַחֲנוֹת רַבִּים עוֹמְדִים שָׁם שֶׁמְּמֻנִּים עֲלֵיהֶם. וְכֻלָּם בְּחֶשְׁבּוֹן עוֹמְדִים, וְעוֹמְדִים שָׁם עַד שֶׁיִּגָּאֲלוּ מִצַּד שֶׁל אָבִיו. וְאִם לֹא אָבִיו, לְעִתִּים עוֹמְדִים לַחֲמִשִּׁים שָׁנָה, וְעוֹשֶׂה בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא טוֹבָה וְנִגְאָל בִּקְרוֹבוֹ שֶׁקָּרוֹב לוֹ אוֹ אָחִיו. וְכַמָּה גְאֻלּוֹת מַזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ אָדָם.</p>\n<p>הַגּוּף הָרִאשׁוֹן מַה יִּהְיֶה מִמֶּנּוּ? שְׁאֵלָה שָׁאֲלוּ לִפְנֵי הַחֲבֵרִים, אִם יִתְקַיֵּם אוֹתוֹ גוּף אִם לֹא. אִם תֹּאמַר שֶׁלֹּא יִתְקַיֵּם, וְכִי יֹאבְדוּ מַעֲשֵׂה יָדָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא?! אִם חַיָּב הָיָה הַרְבֵּה וְלֹא רָאוּי לְהִתְקַיֵּם, לֹא שָׁאַלְתִּי. שֶׁוַּדַּאי נֶאֱבָד וְלֹא יִתְקַיֵּם. אֲבָל כַּמָּה הֵם שֶׁחוֹזְרִים לְזֶה הָעוֹלָם וְנִתְקְנוּ גוּפָם, מַה יִּהְיֶה מִמֶּנּוּ?</p>\n<p>הַגּוּף הַהוּא לֹא נֶאֱבָד, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא יְאַבֵּד מַעֲשֵׂה יָדָיו, וּבְרִיּוֹת מְזֻמָּנוֹת לַעֲשׂוֹת מִמֶּנּוּ. וְאֵלּוּ הָיוּ גוּפִים שֶׁחוֹזְרִים בְּלִי רוּחַ. כַּאֲשֶׁר עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת הַמֵּתִים, אֵלּוּ יִבָּנוּ וְיָקוּמוּ אַרְבָּעִים יוֹם בְּלִי רוּחַ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עֲלֵיהֶם וְשׁוֹלֵחַ עֲלֵיהֶם רוּחַ שֶׁנּוֹשֶׁבֶת בְּגַן עֵדֶן, וְיָקוּמוּ עַל עָמְדָם וְיִהְיוּ שַׁמָּשִׁים לַצַּדִּיקִים שֶׁעוֹסְקִים בַּתּוֹרָה. וְאֵלּוּ יָמוּתוּ כְּמִקֹּדֶם, וְאַחַר כָּךְ יָקוּמוּ לָהֶם,</p>\n<p>וְעַל זֶה כָּתוּב (קהלת ד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, מִזְּמַן קַדְמוֹן. כַּאֲשֶׁר יָקוּמוּ, יֵדְעוּ אֶת קוֹנָם יְדִיעָה שֶׁאֵינָהּ בְּרוּרָה כִּשְׁאָר בְּנֵי אָדָם, וְאֵלּוּ שַׁמָּשִׁים שֶׁל הָעָם הַקָּדוֹשׁ. בְּסִפְרוֹ שֶׁל שְׁלֹמֹה עַל אֵלּוּ הַגּוּפִים כָּתוּב, (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה וְגוֹ' וְאֵלֶּה וְגוֹ'. בֵּין צַדִּיקִים בֵּין רְשָׁעִים - יָקוּמוּ, וְעַל זֶה כָּתוּב בָּהֶם בְּאֹרַח סָתוּם - וְרַבִּים, וְלֹא כָתוּב מִי אֵלּוּ.</p>\n<p>וּמִשּׁוּם כָּל זֶה, אַף עַל גַּב שֶׁאָמַרְנוּ שֶׁנִּשְׁבְּרוּ - לֹא כָּךְ. שֶׁהֲרֵי אֵין לָנוּ גוּף מֵאֵלּוּ שֶׁלֹּא יָקוּמוּ מִדּוֹר הַמַּבּוּל וְדוֹר הַפְּלַגָּה, וְיִשָּׁבְרוּ כְמִקֹּדֶם. דּוֹר הַמַּבּוּל מַה כָּתוּב בָּהֶם? כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ, מַשְׁחִיתִים אוֹתוֹ אֵיבָר. מִשּׁוּם זֶה נֶעֶנְשׁוּ. אַף כָּאן, כָּל אֵלּוּ שֶׁלֹּא זָכוּ לְבָנִים, אֵין לָהֶם חֵלֶק בְּאוֹתוֹ עוֹלָם עַד שֶׁמִּתְתַּקְּנִים. וַאֲפִלּוּ לַחֲמִשִּׁים דּוֹרוֹת מַחֲזִיר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>מִצְוָה לַחֲלֹץ אֶת יְבִמְתּוֹ, הֲרֵי נִתְבָּאֵר הוֹאִיל וְאֵין רָצוֹן שֶׁל זֶה אוֹ שֶׁל זֶה וְלֹא נִתְקַן בַּחֲבִיבוּת, יֵשׁ לַחֲלֹץ. וְאִם תֹּאמַר, בְּמָקוֹם שֶׁמְּצוּיִים חַיִּים יֵשׁ סַנְדָּל בַּיֹּפִי שֶׁל תִּקּוּנֵי הָרַגְלַיִם, שֶׁכָּתוּב (שיר השירים ז) מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים בַּת נָדִיב וְגוֹ', מִשּׁוּם שֶׁזֶּה הוּא מָקוֹם שֶׁמְּצוּיִים בּוֹ חַיִּים.</p>\n<p>וּבְמָקוֹם שֶׁמְּצוּיָה בוֹ מִיתָה אֵין סַנְדָּל כְּלָל, מִשּׁוּם שֶׁהוּא צַד שֶׁאֵין בּוֹ תִּקּוּן שֶׁל רַגְלֵי בְּנֵי אָדָם, וּמִשּׁוּם זֶה אֵין בּוֹ סַנְדָּל. וְכָל אֵלּוּ הַצְּדָדִים שֶׁמִּתְפַּשְּׁטִים מִמֶּנּוּ, כֻּלָּם מְשֻׁנֵּי רַגְלַיִם עַד שֶׁמִּשְׁתַּנֶּה כְּרַגְלֵי הַתַּרְנְגוֹל.</p>\n<p>בְּמַלְכַּת שְׁבָא כָּתוּב (מלכים א י) וַתָּבא לְנַסֹּתוֹ בְּחִידוֹת, אֶחָד שֶׁעָשָׂה לְרַגְלָיו סַנְדָּל שֶׁל הַצַּד הָאַחֵר. מַה כָּתוּב? (שם) וַיַּגֶּד לָהּ הַמֶּלֶךְ אֶת כָּל לְבָבָהּ (דבריה), וְלֹא כָתוּב וַיַּעַשׂ לָהּ. גִּלָּה לָהּ הַסּוֹד וְלֹא הִצְטָרֵךְ לַעֲשׂוֹת לָהּ סַנְדָּל, שֶׁאֵין דֶּרֶךְ לְאוֹתוֹ צַד בָּזֶה.</p>\n<p>וּמִשּׁוּם זֶה מִי שֶׁרוֹאֶה בַחֲלוֹמוֹ שֶׁנּוֹתְנִים לוֹ סַנְדָּלִים לְרַגְלָיו, וַדַּאי שֶׁחַיִּים נִמְסְרוּ לוֹ. וּמִי שֶׁרוֹאֶה שֶׁפּוֹשְׁטִים מִמֶּנּוּ סַנְדָּל, בְּדִין צַד הָאַחֵר יִמָּסֵר אִם לֹא יָשׁוּב. וְעַל זֶה יֵשׁ לִשְׁלֹף לָזֶה וְלָתֵת אוֹתוֹ תּוֹךְ עָפָר,</p>\n<p>סוֹד זֶה סַנְדָּל שֶׁהוּא רָגִיל בּוֹ לֹא יִשְׁלֹף, כְּדֵי שֶׁלֹּא יָסוּר מִמֶּנּוּ. אֲבָל צָרִיךְ סַנְדָּל אַחֵר לִשְׁלֹף מִמֶּנּוּ, וְכַמָּה הֵם. אֵלּוּ בַּעֲלֵי מָגִנִּים בְּאוֹתוֹ צַד שֶׁמִּתְאַסְּפִים שָׁם לְהַנְעִיל אוֹתוֹ סַנְדָּל לְאוֹתוֹ צַד, וְלֹא יְכוֹלִים.</p>\n<p>חוֹזֵר אֵצֶל אוֹתוֹ מֵת וּבָא בִטְעָנוֹת עָלָיו לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לָחוּס עָלָיו, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלָיו. וּמִשּׁוּם אוֹתוֹ סַנְדָּל חוֹזֵר לְאוֹתוֹ מָקוֹם אַרְבָּעִים יָמִים וְסָר מֵאוֹתוֹ מֵת, וְכָל אֵלּוּ בַּעֲלֵי מָגִנִּים שֶׁלּוֹ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לוֹ עֹנֶשׁ וְגוֹאֵל אוֹתוֹ,</p>\n<p>אֲבָל לֹא נִכְנָס תּוֹךְ הַמִּקְדָּשׁ. וּמָקוֹם מְתֻקָּן לָהֶם מִחוּץ לְגַן עֵדֶן, וְשָׁם עוֹמְדִים וּמוֹדִים וּמְשַׁבְּחִים לְהַקָּדוֹשׁ בָּרוּךְ הוּא וְרוֹאִים אוֹתוֹ מֵרָחוֹק וְאֶת אוֹתוֹ הָאוֹר שֶׁל עִדּוּן הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן וּמִתְבַּיְּשִׁים בְּמַעֲשֵׂיהֶם. אַשְׁרֵיהֶם הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522012749,"<p>וְכָל הָאוֹתִיּוֹת הָאֵלּוּ הֵן (דינים) לִצְדָדִים אֲחֵרִים וּלְחַיָּבִים, הֵן כְּשַׁלְשְׁלָאוֹת וּרְמָחִים לָאֵיבָרִים. תְּרוּעָה שַׁלְשֶׁלֶת וּשְׁתֵּי תְרוּעוֹת בַּעֲשָׂרָה שׁוֹפָרוֹת, וְהֵם אֶחָד מִן קשר\"ק, וְשֵׁנִי מִן קר\"ק, וְהֵם הָעַמּוּד הָאֶמְצָעִי. וְלָמַדְנוּ, צַדִּיק</p>\n<p>כָּל אֶחָד הָעַמּוּד הָאֶמְצָעִי - יִשְׂרָאֵל. שְׁלִישִׁיָּה לַתְּקִיעָה שֶׁל אַבְרָהָם רַחֲמִים פְּשׁוּטִים, וְלַשְּׁבָרִים שֶׁל יִצְחָק דִּינִים שׁוֹבְרִים אֶת הַלֵּב, שֶׁשְּׁבָרִים לְשׁוֹן שְׁבִירָה הֵם, זֶהוּ שֶׁכָּתוּב (שמות כג) (ו) שַׁבֵּר תְּשַׁבֵּר מַצֵּבתֵיהֶם. צַדִּיק הוּא שַׁלְשֶׁלֶת שְׁלִישִׁי מְמֻצָּע בֵּין צְבָאוֹת שֶׁלּוֹ שְׁתֵּי שְׂפָתַיִם, תְּקִיעָה לְפָנֶיהָ וּתְקִיעָה לְאַחֲרֶיהָ.</p>\n<p>שְׁתֵּי חֲצוֹצְרוֹת כֶּסֶף נִקְרָאוֹת כַּאֲשֶׁר נוֹטְלִים מֵרַחֲמִים שֶׁהוּא יָמִין. שְׁנַיִם כְּרוּבִים זָהָב נִקְרָאִים מִצַּד הַגְּבוּרָה שֶׁשָּׁם כְּרוּבִים, וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. וְכָל הָעֶשֶׂר נִקְשָׁרִים בְּקֶשֶׁר אֶחָד שֶׁהוּא סִימַן קֶשֶׁ\"ר - תְּקִיעָ\"ה שְׁבָרִי\"ם תְּרוּעָ\"ה.</p>\n<p>כְּנֶגְדּוֹ קֶשֶׁר שֶׁל תְּפִלִּין, וּבֵאֲרוּהוּ חֲכָמִים, הֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה קֶשֶׁר שֶׁל תְפִלִּין, וְזֶה עַמּוּד הָאֶמְצָעִי, קִשּׁוּר שֶׁל שְׁלֹשֶׁת הָאָבוֹת לְמַעְלָה, וְצַדִּיק קִשּׁוּר שֶׁל נֵצַ\"ח הוֹ\"ד יְסוֹ\"ד. וְזֶהוּ קֶשֶׁר בְּתוֹךְ קֶשֶׁר, חוֹתָם בְּתוֹךְ חוֹתָם, לִהְיוֹת הַיַּיִן שֶׁל הַתּוֹרָה שָׁמוּר מִבִּפְנִים,</p>\n<p>וְכָךְ חֻלְיָה אֵין פָּחוֹת מִשָּׁלֹשׁ כְּרִיכוֹת. וְזוֹ הַשְּׁכִינָה שֶׁהִיא בַּת יְחִידָה קְשׁוּרָה בָּאוֹת שִׁי\"ן שֶׁל שַׁבָּת, הִיא אוֹת שֶׁל תְּפִלִּין קְשׁוּרָה בָּאוֹת שִׁי\"ן שֶׁל הַתְּפִלִּין, שֶׁהִיא שְׁלֹשָׁה עֲנָפִים שֶׁל הָאָבוֹת, וְזֶה אוֹתִיּוֹת יֵ\"שׁ שֶׁל שַׁדַּ\"י. נִשְׁאֲרָה אוֹת דָּלֶי\"ת לִהְיוֹת אַרְבָּעָה בָּתֵּי הַתְּפִלִּין. בְּזְהִ הַקֶּשֶׁר נִקְשָׁר שֵׁ\"ד בְּשַׁלְשֶׁלֶת בַּקֶּשֶׁר שֶׁל הַתְּפִלִּין בִּזְמַן שֶׁהוּא קָשׁוּר. אִם יַצִּילֵהוּ אֱלוֹהַּ, יִפְטֹר עַצְמוֹ מִשַּׁלְשְׁלָאוֹת הַמֶּלֶךְ,</p>\n<p>מִשּׁוּם שֶׁתְּרוּעָה הִיא בַּדַּעַת וְהִיא הָעַמּוּד הָאֶמְצָעִי, קֶשֶׁר שֶׁל שְׁלֹשָׁה אָבוֹת. אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה, וְלֹא אָמַר שׁוֹמְעֵי. וּמִיָּד שֶׁנִּקְשָׁר הַשְּׂמֹאל בַּיָּמִין, נִכְפֶּה הַדִּין וּמִתְגַּבְּרִים הָרַחֲמִים.וְהַקֶּשֶׁר שֶׁל שְׁנֵיהֶם - דַּעַת. שַׁלְשֶׁלֶת קְשׁוּרָה בִתְקִיעָה וּשְׁבָרִים.</p>\n<p>וְעַל זֶה פֶּסַח הוּא יָמִין, רֹאשׁ הַשָּׁנָה הוּא שְׂמֹאל, הָעַמּוּד הָאֶמְצָעִי הוּא מַתַּן תּוֹרָה. וְאֵלּוּ שִׁבְעָה בְשִׁבְעָה (ושבעה) מוּצָקוֹת, וְהֵם שְׁכִינָה עֶלְיוֹנָה כְּלוּלָה מִשֶּׁבַע סְפִירוֹת. שְׁכִינָה תַחְתּוֹנָה בַּת שֶׁבַע, וְהֵם אַרְבַּע עֶשְׂרֵה.</p>\n<p>הָעַמּוּד הָאֶמְצָעִי כָּלוּל מִשְּׁנֵיהֶם בְּי\"ד - יְהֹוָ\"ה יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְכָל שֶׁבַע מִצַּד הַשְּׁכִינָה. זֶהוּ שֶׁכָּתוּב (תהלים קיט) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךְ. כְּנֶגְדָּהּ עוֹשִׂים שֶׁבַע הַקָּפוֹת.</p>\n<p>סוּכָּ\"ה יאהדונה\"י, כ\"ו ה\"ס. וְהַקָּדוֹשׁ בָּרוּךְ הוּא לוּלָב, וְהַשְּׁכִינָה אֶתְרוֹג. לוּלָב דּוֹמֶה לַגּוּף, וְאֶתְרוֹג דּוֹמֶה לַלֵּב. וּבַגּוּף יֵשׁ שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת, לוּלָב שְׁמוֹנָה עָשָׂר נִעְנוּעִים שֶׁל הַלּוּלָב. וּבִנְטִילַת הַלּוּלָב שְׁמוֹנָה עָשָׂר נִעְנוּעִים בְּאָנָּא ה', שְׁמוֹנָה עָשָׂר נִעְנוּעִים בְּהוֹדוּ לַה', שְׁמוֹנָה עָשָׂר נִעְנוּעִים תְּחִלָּה וָסוֹף - ע\"ב. לְהַבְרִיחַ בָּהֶם ע\"ב מְמֻנִּים שֶׁמְּמֻנִּים עַל רוּחוֹת רָעוֹת וּטְלָלִים רָעִים.</p>\n<p>שִׁבְעַת יְמֵי הַסֻּכָּה - שֶׁבַע סְפִירוֹת. סֻכָּה - אִמָּא עֶלְיוֹנָה שֶׁמְּסוֹכֶכֶת עֲלֵיהֶם. נִסּוּךְ הַמַּיִם וְנִסּוּךְ הַיַּיִן - מִצַּד שֶׁל יָמִין וּשְׂמֹאל, וְחַג שְׁמִינִי חַג עֲצֶרֶת שְׁכִינָה תַחְתּוֹנָה, בַּת הַמֶּלֶךְ וְהַמַּלְכָּה.</p>\n<p>אֵלֶּה מוֹעֲדֵי ה' מִקְרָאֵי קֹדֶשׁ אֲשֶׁר תִּקְרְאוּ אֹתָם בְּמֹעֲדָם. לְצִפּוֹר שֶׁמְּצַפְצְפִים לָהּ בָּנֶיהָ בְּכָל יוֹם בְּכַמָּה צִפְצוּפִים, וְהִיא רוֹבֶצֶת עֲלֵיהֶם. אַחַר שֶׁנִּגְדְּלוּ כַנְפֵיהֶם שֶׁל בָּנֶיהָ, עָפוּ כֻלָּם אַחַר אִמָּם. צַיָּד אֶחָד הָיָה חָכָם, רָצָה לָצוּד אוֹתָם. מֶה עָשָׂה הַצַּיָּד? נָטַל אֶת הָאֵם שֶׁלָּהֶם וְקָשַׁר אוֹתָהּ, וְהִיא צוֹוַחַת בִּגְלַל בָּנֶיהָ. שָׁמְעוּ הַבָּנִים קוֹלָהּ וְיָרְדוּ אֶצְלָהּ וְקָשְׁרוּ אוֹתָם. כְּמוֹ זֶה הָאִמָּא הָעֶלְיוֹנָה שֶׁנֶּאֱמַר בָּהּ (דברים כב) וְהָאֵם רֹבֶצֶת עַל הָאֶפְרֹחִים אוֹ עַל הַבֵּיצִים, וְאֵלּוּ יִשְׂרָאֵל מְצַפְצְפִים אֵלֶיהָ בְּכַמָּה צִפְצוּפִים שֶׁל תְּפִלּוֹת וְכוּ': (עד כאן מההשמטות)</p>"],[9522012750,"<p>שָׁנוּ רַבּוֹתֵינוּ, כְּשֶׁחָלָה רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, נִכְנְסוּ לְפָנָיו רַבִּי פִּנְחָס וְרַבִּי חִיָּיא וְרַבִּי אַבָּא. אָמְרוּ לוֹ, מִי (שהוא) עַמּוּדוֹ שֶׁל הָעוֹלָם, שׁוֹכֵב (מת) ?! אָמַר לָהֶם, לֹא בֵּית דִּין שֶׁל מַעְלָה מְעַיְּנִים בְּדִינִי, שֶׁהֲרֵי אֲנִי רוֹאֶה שֶׁאֵין אֲנִי נִתָּן לַמַּלְאָךְ וְלַדַּיָּן שֶׁל מַעְלָה, שֶׁאֲנִי לֹא כִשְׁאָר בְּנֵי אָדָם.</p>\n<p>אֶלָּא זֶה הַדִּין שֶׁלִּי, הַקָּדוֹשׁ בָּרוּךְ הוּא דָּן אוֹתוֹ וְלֹא בֵית דִּינוֹ. וְזֶה שֶׁאָמַר דָּוִד בְּבַקָּשָׁתוֹ לְפָנָיו, (תהלים מג) שָׁפְטֵנִי אֱלֹהִים וְרִיבָה רִיבִי. וְכֵן שְׁלֹמֹה אָמַר, (מלכים א ח) לַעֲשׂוֹת מִשְׁפַּט עַבְדּוֹ, הוּא לְבַדּוֹ וְלֹא אַחֵר.</p>\n<p>שֶׁהֲרֵי לָמַדְנוּ, כְּשֶׁאָדָם חוֹלֶה, בֵּית דִּין שֶׁל מַעְלָה מִסְתַּכְּלִים בְּדִינָיו., יֵשׁ מֵהֶם שֶׁנּוֹטִים לְכַף זְכוּת, שֶׁמַּרְאִים זְכוּתוֹ שֶׁל הָאָדָם, וְיֵשׁ מֵהֶם שֶׁנּוֹטִים לְכַף חוֹבָה, שֶׁמַּרְאִים חוֹבָתוֹ שֶׁל הָאָדָם. וְלֹא יוֹצֵא אִישׁ מִן הַדִּין כְּמוֹ שֶׁהָיָה רוֹצֶה.</p>\n<p>אֲבָל מִי שֶׁדָּן אוֹתוֹ הַמֶּלֶךְ הָעֶלְיוֹן, שֶׁשּׁוֹלֵט עַל הַכֹּל - הוּא טוֹב, וְלֹא יָכוֹל אָדָם לִהְיוֹת בַּדִּין הַזֶּה חוּץ מִטּוֹב. מַה טַּעֲמוֹ? שֶׁהֲרֵי שָׁנִינוּ, מִדּוֹתָיו שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן נוֹטִים לִזְכוּת תָּמִיד, וְהוּא כֻּלּוֹ צַד שֶׁל הָאֱמוּנָה, וּבְיָדוֹ לַעֲזֹּב לַחֲטָאִים וְחוֹבוֹת. זֶהוּ שֶׁכָּתוּב (תהלים קל) עִמְּךְ הַסְּלִיחָה. לְמַעַן תִּוָּרֵא. עִמְּךְ וְלֹא עִם אַחֵר.</p>\n<p>וּמִשּׁוּם זֶה בִּקַּשְׁתִּי מִלְּפָנָיו שֶׁהוּא יָדוּן דִּינִי, וַאֲנִי אֶכָּנֵס בִּשְׁלֹשָׁה עָשָׂר פְּתָחִים לָעוֹלָם הַבָּא, וְעוֹד, שֶׁלֹּא עָבְרוּ אוֹתָם חוּץ מֵהָאָבוֹת, וְלֹא יִהְיֶה מִי שֶׁיִּמְחֶה בְיָדִי, שֶׁלֹּא אֶתְבַּע רְשׁוּת מֵהֶם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן דָּבָר, וְרָאוּ בֵית חָלְיוֹ שֶׁלֹּא הָיָה שָׁם. תָּמְהוּ, וְלֹא יָכֹל אֶחָד מֵהֶם לְדַבֵּר בְּפִיו מֵאֵימָה גְדוֹלָה שֶׁהָיְתָה עֲלֵיהֶם. עַד שֶׁהָיוּ יוֹשְׁבִים, עָלָה לָהֶם רֵיחוֹת שֶׁל בְּשָׂמִים רַבִּים וְכָל אֶחָד הִתְיַשֵּׁב. עַד שֶׁרָאוּ לְרַבִּי שִׁמְעוֹן, וְהָיָה מְדַבֵּר דְּבָרִים, וְלֹא הָיוּ רוֹאִים אֲחֵרִים חוּץ מִמֶּנּוּ.</p>\n<p>לְאַחַר זְמַן אָמַר לָהֶם רַבִּי שִׁמְעוֹן, רְאִיתֶם מַשֶּׁהוּ? אָמַר לוֹ רַבִּי פִּנְחָס, לֹא. אֶלָּא כֻּלָּנוּ תְמֵהִים עַל שֶׁלֹּא רָאִינוּ אוֹתְךְ בְּבֵית חָלְיְךְ זְמַן רַב, וְכַאֲשֶׁר רָאִינוּ אוֹתְךְ, עָלָה לָנוּ רֵיחוֹת בְּשָׂמִים שֶׁל גַּן עֵדֶן, וְשָׁמַעְנוּ קוֹל אֶחָד מְדַבֵּר, וְלֹא יָדַעְנוּ מִי מְדַבֵּר עִמְּךְ.</p>\n<p>אָמַר לָהֶם, וְלֹא שְׁמַעְתֶּם דָּבָר אַחֵר חוּץ מִמֶּנִּי? אָמְרוּ, לֹא. אָמַר לָהֶם, אֵין אַתֶּם רְאוּיִים לִרְאוֹת סֵבֶר פָּנָיו שֶׁל עַתִּיק הַיָּמִים.</p>\n<p>אָמַר לָהֶם, אֹמַר לָכֶם דָּבָר, תָּמַהְתִּי עַל רַבִּי פִּנְחָס שֶׁלֹּא רָאָה, שֶׁאֲנִי רָאִיתִי אוֹתוֹ כָּעֵת בָּעוֹלָם הַבָּא, לְמַטָּה מִמֶּנּוּ מֵרַבִּי אֶלְעָזָר בְּנִי.</p>\n<p>וְכָעֵת שָׁלְחוּ בִּשְׁבִילִי מִלְמַעְלָה וְהֶרְאוּ לִי מָקוֹם שֶׁל הַצַּדִּיקִים לָעוֹלָם הַבָּא, וְלֹא הִתְיַשֵּׁב בְּלִבִּי מְקוֹמִי, חוּץ מֵעִם אֲחִיָּה הַשִּׁילוֹנִי. וּבָרַרְתִּי מְקוֹמִי וּבָאתִי, וּבָאוּ עִמִּי נְשָׁמוֹת שֶׁל צַדִּיקִים, וְעֶלְיוֹן מֵהֶם מִנִּשְׁמוֹת הַצַּדִּיקִים - אָדָם הָרִאשׁוֹן, שֶׁהָיָה יוֹשֵׁב אֶצְלִי וְהָיָה מְדַבֵּר עִמִּי, וּבִקֵּשׁ שֶׁלֹּא יִתְגַּלֶּה חֶטְאוֹ לְכָל הָעוֹלָם, חוּץ מֵאוֹתוֹ שֶׁאָמְרָה הַתּוֹרָה בִּגְלָלוֹ וְנִסְתָּר בְּאוֹתוֹ אִילָן שֶׁל גַּן עֵדֶן.</p>\n<p>וַאֲנִי אָמַרְתִּי לוֹ שֶׁהֲרֵי הַחֲבֵרִים (כבר) גִּלּוּ. אָמַר, אוֹתוֹ שֶׁגִּלּוּ הַחֲבֵרִים בֵּינֵיהֶם - טוֹב, אֲבָל שְׁאָר בְּנֵי הָעוֹלָם לֹא. מָה הַטַּעַם? שֶׁחָס הַקָּדוֹשׁ בָּרוּךְ הוּא עַל כְּבוֹדוֹ וְלֹא רָצָה לְפַרְסֵם חֶטְאוֹ, אֶלָּא בְּאוֹתוֹ אִילָן שֶׁאָכַל מִמֶּנּוּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא גִּלָּה לוֹ בַּסּוֹד הַקָּדוֹשׁ לַחֲבֵרֵינוּ, חֲבֵרִים שֶׁלֹּא יְדַבְּרוּ הֵם בָּהֶם בֵּינֵיהֶם, וְלֹא לָרַוָּקִים מֵהַחֲבֵרִים וּלְאֵלּוּ שֶׁיָּבאוּ לָעוֹלָם.</p>\n<p>וְהוּא דָבָר שֶׁלֹּא צָרִיךְ כָּל אָדָם, וְטוֹעֶה בוֹ, לֹא מִשּׁוּם הַחֵטְא שֶׁחָטָא, אֶלָּא מִשּׁוּם כְּבוֹד הַשֵּׁם הָעֶלְיוֹן שֶׁבְּנֵי אָדָם לֹא זְהִירִים בּוֹ, וְכָתוּב (שמות ג) זֶה שְּׁמִי לְעֹלָם. וְיָבֹאוּ לִשְׁאֹל מַה שֶּׁלֹּא צָרִיךְ לָהֶם.</p>\n<p>וְזֶה שֶׁכָּתוּב (שמות יט) פֶּן יֶהֶרְסוּ אֶל ה' לִרְאוֹת וְנָפַל מִמֶּנּוּ רָב. הָרַב נוֹפֵל וְנִתְפָּס בְּאוֹתוֹ עָוֹן. כָּךְ אֲנִי גּוֹזֵר, אֵלּוּ הַחֲבֵרִים (חבר) שֶׁמְּלַמְּדִים הַשֵּׁם הַקָּדוֹשׁ, הוּא נוֹפֵל וְנִמְצָא בְּאוֹתוֹ חֵטְא יוֹתֵר מֵהֶם, שֶׁכָּתוּב וְנָפַל מִמֶּנּוּ רָב. הָרַב נוֹפֵל וְנִתְפָּס בְּאוֹתוֹ עָוֹן.</p>\n<p>קָרַב אֶצְלוֹ רַבִּי אֶלְעָזָר בְּנוֹ. אָמַר לוֹ, אַבָּא, מָה אֲנִי שָׁם? אָמַר לוֹ, (אשרי חלקך בני, זמן רב יהיה שלא תקבר אצלי, אבל) בְּנִי, שֶׁלֹּא תִזָּכֵר כָּאן. אֲבָל בְּאוֹתוֹ עוֹלָם, מָקוֹם שֶׁלְּךְ וְשֶׁלִּי מְבֹרָרִים. זַכָּאִים אֲנַחְנוּ עִם אֵלּוּ הַצַּדִּיקִים שֶׁמְּזֻמָּנִים לְשַׁבֵּחַ לַאֲדוֹן הָעוֹלָם, שֶׁאֵלּוּ הַמַּלְאָכִים שֶׁמְּשַׁמְּשִׁים לְפָנָיו. זֶהוּ שֶׁכָּתוּב (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ.</p>"]]});
